SY_TALK("iJmW6J8zWRo.hi",[[1,["क्योंकि बहुत लोगों ने इस पर लिखा है","(अस्पष्ट) और बहुत से लोग सोचते रहे हैं कि"]],[8,["इस मामले में कुछ करना चाहिए कि","सत्य को खोजने का है। (अस्पष्ट)"]],[19,["अब जब मानव (अस्पष्ट) तो उसकी ऐसी स्तिथि होती","है कि वो सिर्फ इस चीज़ को मानता है (अस्पष्ट)","और उसके पास कोई माध्यम नहीं है।"]],[37,["जैसे कि साइंस की उपलब्धि जो हुई है, यह हमने","सिर्फ बुद्धि के ही माध्यम से देखा है।"]],[45,["लेकिन बुद्धि जो है, वो दृश्य जो संसार में","है, उसी के बारे में बातें करता है। जो अदृश्य","है उसे नहीं बता सकता।"]],[56,["और सत्य और अदृश्य में क्या अंतर है","यही नहीं बता सकता।"]],[61,["तब पहले यह सोचना चाहिए, कि जब सत्य की खोज","की इंसान बात करता है, तो सर्वप्रथम उसको","यही विचार करना होगा"]],[71,["कि जो कुछ हमने बुद्धि से जाना, कुछ भी नहीं","जाना, तो भी हम भ्रम में बने रहे।"]],[77,["बुद्धि से जानी हुई बात, जितनी भी हमने आज","तक जानी है, उससे इतना ज़रूर हुआ,"]],[84,["जो दृश्य में है उससे हमने ज्ञात (अस्पष्ट)","लेकिन जो कुछ अदृश्य में है वो भी नहीं जाना"]],[90,["और ये भी नहीं जान पाए कि वो आखिर जो हमने","दृश्य में जानना है यह परम सत्य है या नहीं।"]],[99,["अब साइंस की उपलब्धि जब हमारी है, तो साइंस","के हम अपने सिर हुए, साइंस में हमने बहुत","सारी बातें जानी।"]],[107,["अणु परमाणु तक हम पहुँच चुके। गतिविधियों को जो","समझा है, वो भी सब जो कुछ भी जड़ है, उसके बारे में।"]],[120,["..... हरएक के साथ किस तरह से होता है संसार","में, इसकी ओर किसी की भी दृष्टि नहीं है।"]],[127,["सत्य के अन्वेषण में सबसे प्रथम बात ये सोचनी","चाहिए, कि जो कुछ मनुष्य कर सकता है,","उससे परे कोई सृष्टि है या नहीं।"]],[138,["जैसे कि जीवंत वस्तु को हम देखते हैं मनुष्य का","चलना, टहलना, उसका बढ़ना,","उद्विग्नत होना, सब कुछ देखते हैं"]],[147,["लेकिन हम इस ओर नज़र नहीं करते, इस तरफ हमारी","दृष्टि नहीं पड़ पाती है, कि यह आदमी बनाया गया है","सो क्यों - पहली बात,"]],[160,["क्योंकि उसका उत्तर हमारे पास नहीं है। मनुष्य की","विशेषता यह है कि जिसका उसके पास उत्तर नहीं,","उधर से मुँह मोड़ लेता है।"]],[170,["और कहता है कि, जिसका हम उत्तर दे सकते हैं,","वहीँ तक हम रहेंगे, उससे परे जाना भी, वो सोचता है","कि गलत बात हो जाएगी।"]],[181,["लेकिन मनुष्य संसार में आया, साइंस ने बताया,","कि एक अमीबा से ही मनुष्य बना है।"]],[189,["जो हटात दिमाग में ये बात आनी चाहिए कि यह","इस तरह की जो विशेष चीज़ की घटनाएँ घटित हुईं"]],[198,["और जिसकी वजह से ये सब हमसे निम्न हैं,","ये जड़ वस्तु हैं, इसको हम बना सकते हैं।"]],[206,["मनुष्य की दृष्टि वहाँ तक पहुँचती है, कि भई","हम इसे बना रहे हैं, तो इसे हमने बनाया और हम","बहुत ऊँचे इंसान हो गए।"]],[213,["या हमने बड़ा भारी काम कर दिया। लेकिन इसमें","का एक पत्थर भी इंसान नहीं बना सकता, एक","अणु रेणु कुछ भी नहीं बना सकता।"]],[222,["थोड़े नम्रता पूर्वक मनुष्य सोचे कि,","\"क्या मैं ये पत्थर स्वयं बना सकता हूँ?"]],[231,["जितने भी एलिमेंट्स हैं, उसमें से मैं","एक भी एलिमेन्ट ख़ुद बना सकता हूँ?"]],[238,["उसकी वैलेंसीस आदि इस कदर सुंदरता से बनी हुईं","हैं, क्या मैं ऐसी कोई रचना कर सकता हूँ?\""]],[244,["ये तो ठीक है मरी हुई चीज़ को जोड़ दिया।","लेकिन उनकी रचना में आप कुछ भी","इंटरफेरेंस कर सकते हैं उसमें"]],[254,["कोई आपका हस्तक्षेप हो सकता है - नहीं हो सकता है।","आप कोई चीज़ उसमें की बदल नहीं सकते।"]],[262,["वो जैसी है, वैसी ही रहेगी। आप उसके कंपाउंड्स","बना सकते हैं मिक्सचर्स बना सकते हैं"]],[270,["लेकिन अगर सल्फर को जलाया जाए और उसके","क्रिस्टल बनाइये तो उसी ढंग के बनेंगे जैसे","सल्फर के बनते हैं।"]],[280,["अब अगर चाहें कि अपनी तरह के क्रिस्टल बनाएँ,","तो वो तक आप नहीं बना सकते हैं।"]],[285,["उसकी जो प्रॉपर्टीज हैं, उसपर आपका हस्तक्षेप नहीं है।","हाँ उन प्रॉपर्टीज तो आप इस्तेमाल कर सकते हैं"]],[292,["लेकिन उनकी जो बुनियादी फंडामेंटल जो प्रॉपर्टीज","हैं, उसको आप नहीं बदल सकते हैं।"]],[304,["तो ये किसने बनाया है और ये किसकी शक्ति","में हैं कि जो इसे बदल सकता है? इधर भी एक","दृष्टि क्षेप होना चाहिए।"]],[313,["अँधेरे में रह कर के आप ये कहें कि उजियारा","नहीं है, तो ये तो बात गलत होगी।"]],[320,["लेकिन अगर कोई कहता है कि उजियारा है, तो","कोई साइंटिस्ट हो, कोई भी बुद्धिजीवी आदमी हो,"]],[327,["उसको कहना चाहिए कि अगर उजियारा है तो","देखना चाहिए। कुतूहल तो होना ही चाहिए।"]],[332,["मनुष्य के मन में कुतूहल होना चाहिए कि, आखिर","ये अगर कह रहा है कि इसके परे कोई प्रकाश है,","तो क्यों न देखा जाए?"]],[341,["लेकिन इस तरह से हम अपने ही से प्रभावित हैं,","ऑटोहिप्नोसिस में इतना ज़्यादा हैं,"]],[348,["कि हम सोचते हैं कि, जिसपर हम हाथ चला सकते","हैं, वही चीज़ सत्य है और जिस पर हम हाथ नहीं","चला सकते, उधर देखने की ज़रुरत नहीं।"]],[357,["इस तरह से हम सत्य से कितने दूर हैं ये समझ","सकते हैं आप कि उसके तो हमने मूलभूत","चीज़ों को ही छुआ नहीं"]],[367,["पहला प्रश्न ये, कि ये सृष्टि रची तो रचाई किसने","और इस सृष्टि के अणु, रेणु, परमाणु जितने भी हैं,"]],[374,["उसमें इतनी सुन्दर व्यवस्था किसने की, उनको","इतने व्यवस्थित रूप से किसने बनाया,","ये व्यवस्थापक कौन है?"]],[386,["एक चीज़ कह सकते हैं कि, ईमानदार हैं लोग,","कि कहते हैं कि हम इससे आगे नहीं बढ़ सकते,","तो हम यहीं तक रहते हैं।"]],[392,["पर अगर हम कहते हैं, आप बढ़ सकते हैं,","इससे आगे आप जा सकते हैं,"]],[399,["और इससे आगे एक प्रांगण और भी है, एक डायमेंशन","और भी है, तो क्यों न अपनी आँख खोलें ये सब?"]],[411,["सिर्फ हमारे पास एक अहंकार मात्र है कि, \"हमने ये","किया, हमने ये पता लगाया, हमारे पास ये है, वो है,\"","लेकिन जो भी है वो आपसे निम्न ही है।"]],[425,["अगर आपको ऊपर उठना है, कहीं भी, तो ऊपर","की चीज़ पकड़नी पड़ती है।"]],[433,["कहीं भी चढ़ना होता है, आपने देखा होगा कि जब लोग","किसी बड़े पहाड़ी पर चढ़ते हैं, तो वहाँ पर ऊपर पहले","कील ठोकते हैं फिर उसको पकड़ते हैं।"]],[443,["इसी को आप साइंस में हाइपोथिसिस आदि कहते","हैं, कि जहाँ एक धारणा बनानी होती है।"]],[448,["उस धारणा की कील थोक दी, फिर उस कील को","पकड़ के आप ऊँचे उठ गए, और फिर उससे","आगे जा के देखा कि क्या होता है।"]],[457,["वास्तविक ये कील ठोकी है या नहीं, वहाँ पर हम","पहुँचे हैं या नहीं, ये यथार्थ में पहुँच के ही","मनुष्य देख सकता है।"]],[466,["लेकिन एकदम मुँह मोड़ लेने से ये काम","नहीं होने वाला।"]],[472,["अब अगर हम ये कहें कि जो बड़े-बड़े संत-साधु हो गए,","जो बड़े-बड़े यहाँ पर अवतार हो गए हैं, इस अपने","भारतवर्ष में, इस योग भूमि में,"]],[481,["जिन्होंने बड़े-बड़े महान कार्य किए, जिनको","आज तक संसार पूज रहा है और मान रहा है,"]],[487,["ये लोग झूठ नहीं बोलते थे, तो आप कहेंगे कि,","\"हाँ, झूठ बोलते थे, इसका क्या प्रूफ है?\""]],[493,["अगर आप कहें तो हम आपके हाथ","नहीं पकड़ सकते ना।"]],[498,["परमात्मा है या नहीं, ये भी अब अगर वाद-विवाद","उठे, तो हम आपका हाथ नहीं पकड़ सकते हैं।"]],[505,["लेकिन अगर हम कहें कि इसकी हम सिद्धता आपको","दे सकते हैं, तो क्यों न उस तरफ हम आगे बढ़ें।"]],[512,["अगर सत्य के आप पुजारी हैं और सत्य को आप","जानना चाहते हैं, गर कोई कहता है कि इसमें","आप अग्रसर हो सकते हैं,"]],[520,["इतना ही नहीं पर उस सत्य को आप पूरी तरह से जान","सकते हैं, तो क्यों न हम इसे अत्यंत नम्रतापूर्वक","स्वीकार करें कि"]],[528,["\"चलें भई, कौन सा वो मार्ग माँ बता रहीं","हैं, देखें तो सही है भी कि नहीं।\""]],[533,["अभी तक मान लिया, कि ये चीज़ जागतिक नहीं","थी, सामूहिक नहीं थी और लोग, बहुत थोड़े,","इस बारे में जानते थे"]],[541,["इसलिए गलत फहमियां हो गईं, लेकिन जिस","तरह साइंस की चीज़ है, बिजली आदि चीज़ें","जितनी भी अन्वेषित हैं,"]],[548,["ये जिस तरह आज सामूहिक हैं और जागतिक हैं","और सर्वहित के लिए उपयोग में लाईं जातीं हैं"]],[554,["इससे ऊपर की चीज़ को जब पाना है, तब जो","चीज़ें आजतक हमने इस्तेमाल करीं"]],[561,["अपने से नीचे वाली चीज़ों को पाने के लिए और","हस्तगत करने के लिए, इतना ही नहीं,"]],[566,["उनपर अधिकार जमाने के लिए, उस चीज़","का उपयोग छोड़ देना पड़ेगा।"]],[570,["जैसे कि, दिल्ली में घूमना है, तो मोटर ठीक है","लेकिन ऊपर जाना है तो वायुयान चाहिए।"]],[577,["उसकी गति भी अलग होती है, उसका तौर-तरीका","अलग होता है, उसके सारे प्रकल्प अलग होते हैं।"]],[584,["मोटर की जो है वो चीज़ और है, वो ज़मीन पर चलती","है और ये आकाश पे उड़ने वाला वायुयान है।"]],[590,["इसी प्रकार, जब आपके लिए मैं कह रही हूँ,","कि आपको आत्मा को जानना होगा"]],[595,["आत्मा को इस्तेमाल करना होगा, आत्मा ही","के सहारे आप परमात्मा को जान सकते हैं,"]],[603,["तो इसका मतलब ये है कि जो बुद्धि के सहारे","सारे संसार को आप समझते हैं, आपने जान लिया है,"]],[609,["तो उससे परे कोई चीज़ आपको पानी पड़ेगी","- वो है आत्मा।"]],[614,["साइंस में अगर आत्मा का उल्लेख नहीं है,","तो इतना ही कहना चाहिए कि"]],[618,["आप अभी तक साइंस उस ओर बढ़ नहीं पा रहा,","वह कभी जान भी नहीं पाएगा"]],[623,["क्योंकि जिस मर्यादित क्षेत्र से आप उसे जानना","चाहते हैं, उससे वो परे है, उससे आप देख ही","नहीं पाएँगे।"]],[632,["उसका रेंज जो है, वही नहीं है कि वो उसको","जान पाए। सो इस मशीनरी का जो रेंज है,","वह बढ़ाना पड़ेगा।"]],[643,["और उस रेंज को बढ़ाते वक़्त अगर हम कहें कि","इसमें आत्मा की दृष्टि जब तक नहीं आएगी"]],[649,["तब तक कार्य नहीं हो सकता है, तो आपको मान्य","करना चाहिए कि वह हमें प्राप्त हो।"]],[656,["जैसे हम देखते हैं एक साहब के पास बड़ा","अच्छा माइक्रोस्कोप है,"]],[661,["उससे वह देखता है, कि हर एक पेशियाँ कैसीं हैं","और उसमें रक्त का चलन-वलन कैसा है,","ये सब हम देखते रहते हैं,"]],[670,["लेकिन जब देखते हैं कि दूसरे आदमी के पास कोई","अच्छी मशीन है, इससे भी ज़्यादा, तो हम चाहते हैं","कि किसी तरह से इसे पा लें हस्तगत कर लें।"]],[679,["उसी प्रकार, अगर एक मनुष्य देखता है कि","दूसरे आदमी के पास कोई विशेष चीज़ है,"]],[684,["तो उसको इच्छा यही होनी चाहिए कि उस विशेष","चीज़ को हम पा लें, लेकिन होता नहीं।"]],[691,["आत्मा के बारे में ऐसा नहीं है क्योंकि मनुष्य","यही जानना चाहता है कि, \"जो आज मैं हूँ,"]],[698,["इसी से मुझे सब मिलना चाहिए और इससे आगे","मैं उठूँ, माने ये मेरे साथ अपना ही अनादर है।\""]],[707,["साइंस के मामले में ऐसा नहीं सोचता। साइंस के","मामले में अमेरिका ने कुछ अन्वेषण किया","तो वहाँ भागा जायेगा।"]],[714,["तब नहीं सोचता कि हम हिंदुस्तानी हैं, हम क्यों उनके","पीछे भागें। कुछ अगर रूस ने किया तो उनके पीछे","भागा जायेगा।"]],[722,["लेकिन कुछ अगर अन्वेषण और किसी प्रांगण में","हुआ, तो उसकी ओर मनुष्य की रूचि नहीं होती।"]],[734,["बाहर के पेड़ के बारे में मनुष्य सब जानता है,","लेकिन इसके मूल के बारे में कुछ नहीं जानता है।"]],[740,["और उसके मूल को जानने के लिए आपको सूक्ष्म","होना पड़ेगा और वो सूक्ष्मता आपको पाने के लिए","आपको नम्रता चाहिए।"]],[751,["अगर आप चाहें कि अपने बुद्धि के दम पर आप","उसे पा लें तो नहीं पा सकते उसे।"]],[758,["ये एक सीधी बात लोगों के समझ में नहीं आती","है। जब भी मैं भाषण आदि देतीं हूँ, कुछ भी"]],[763,["तो मैं देखतीं हूँ पहला प्रश्न ये होता है,","कि फलानी किताब में ऐसा लिखा है।"]],[768,["हो गया फिर, बात क्या करें? अरे भई, जो भी लिखा है","वो आपकी बुद्धि से तो आंकलन नहीं होने वाला।"]],[776,["उसको आप नहीं समझ पाएंगे। हम कह रहे हैं","कि नहीं समझ पाएंगे।"]],[779,["समझ लीजिए, बगैर चश्मे के हमें दिखाई नहीं देता है","तो हमें चश्मा लगाना ज़रूरी है - यह तो बात","हमारे समझ में आती है।"]],[785,["और अगर आत्मा के सिवा हम परमात्मा को नहीं","समझ पाते, तो आत्मा को पाना चाहिए - सीधी-साधी","बात क्यों नहीं समझ में आनी चाहिए।"]],[792,["उसमें शंका-कुशंका करने से क्या","आप सत्य को खोज पाएंगे?"]],[796,["अगर आप वास्तव में सत्य के पुजारी हैं और","वाकई आप सत्य को जानना चाहते हैं,"]],[801,["तो सबसे पहले नम्रता होनी चाहिए कि अभी","तक हमने सत्य को पाया नहीं है"]],[812,["ये बहुत बड़ा गुण है - नम्रता।"]],[818,["मनुष्य कुछ भी सीख लेता है लेकिन","नम्रता नहीं सीख पाता।"]],[828,["नम्रता में आप करते क्या हैं? कुछ किसी लोगों","को ऐसा विचार आता है, कि नम्र होने का मतलब","है, आप किसी के आगे झुक गए।"]],[837,["ये बहुत गलत फहमी है। नम्रता का मतलब होता है","कि आपने अपने को खोल दिया है कि स्वीकार करें।"]],[846,["कोई नई विचारधारा को स्वीकार करें। कोई नई","बात को आप स्वीकार करें, देखें, परखें,","समझें, इसमें उतरें।"]],[858,["नम्रता का कभी भी ये मतलब नहीं होता है","कि आप किसी के आगे झुक जाएँ।"]],[863,["जैसे कि पेड़ कि शाखाएं कितनी भी ऊँची उठ","जाएँ, जब तक उसकी जड़ें नीचे तक"]],[869,["ज़मीन खोद कर के स्त्रोत तक नहीं पहुँच जाएँ,","उस पेड़ में कोई सी भी शक्ति नहीं आ सकती है।"]],[875,["उसी प्रकार आपकी कितनी भी सभ्यता बढ़ जाए","और कितना भी ये साइंस का झमेला बढ़ जाए,"]],[883,["लेकिन जब तक आपने अपनी आत्मा को नहीं खोजा","है, ये सारा का सारा जो है, बिलकुल एक बबुले जैसा","नष्ट हो जाएगा, ख़त्म हो जाएगा।"]],[897,["इसमें से कुछ भी नहीं बचने वाला। और वही हो","रहा है, संसार भर में यही हो रहा है।"]],[903,["अभी एक देवीजी मुझे मिलीं। कहने लगीं कि","हम आर्मामेंट के डिसआर्मामेण्ट के लिए गए,"]],[908,["इतनी मेहनत करी लोगों से कहा डिसआर्मामेण्ट","करिए और डिसआर्मामेण्ट करने से ठीक हो","जाएगा और बड़े झगडे हुए"]],[915,["और चार महीने हमने वहाँ मेहनत करी और किसी ने","कोई बात नहीं मानी और [we were great failures]","हम बड़े असफल रहे।"]],[921,["बताइये। इसका मतलब है कि मनुष्य की","बुद्धि ही बिलकुल उसको छुट्टी दे गई।"]],[931,["डिसारमामेंट होना चाहिए - एक सर्व-साधारण मनुष्य","समझ सकता है कि मनुष्य, मनुष्य को मारते फिरे","इसकी क्या ज़रुरत है?"]],[941,["एक आदमी छोड़ कर के कोई सा भी जानवर हाथ","में आर्म्स ले कर के आपस में मारता नहीं है।","उसको पकड़ने की ही शक्ति नहीं होती है।"]],[951,["भगवान ने हमको हाथ दे दिए तो अब उसमें हम","बंदूकें ले कर के दूसरों को मारते हैं। ये बड़ी","अकल की बात है क्या?"]],[960,["इसका इलाज साइंस तो नहीं कर सकती है।","कर सकती है क्या?"]],[965,["लोगों के अंदर सुबुद्धि भरने का इलाज, अगर","साइंस वाले कर दे तो हम मान जाएँ।"]],[975,["किसी के अंदर भी सुज्ञता नहीं आ सकती, साइंस से,","चाहे वह बनाना चाहे तो एटम बम बना दे"]],[982,["और चाहे वो तो एक आदा अच्छा अस्पताल भी","बना सकता है। पर ये चाहने पर है।"]],[990,["ये कोई अचल चीज़ नहीं है, ये चलायमान है। आज","वो बड़ा अस्पताल बनाएगा बड़ा भारी एक","रुग्णालय बनाएगा"]],[997,["वहाँ हज़ारों लोगों को वो ठीक करेगा और उसके","बाद एक दिन अकस्मात् उसी पर बम गिरा कर","के उसका सर्वनाश भी कर सकता है।"]],[1006,["कोई आप उसकी गारंटी नहीं दे सकते हैं।","क्या साइंस इसकी गारंटी देता है"]],[1011,["कि जो आदमी आज साइंस की वजह से अच्छा","काम कर रहा है कल उसका विध्वंस नहीं करेगा?"]],[1017,["मनुष्य की कोई गारंटी आप दे सकते हैं","क्या साइंस से?"]],[1028,["जब साइंस इतना अधूरा पड़ा हुआ हैं तब यह देखना","चाहिए इसका जो प्रकाश है वो इतना धुंधला क्यों है?"]],[1041,["इसके प्रकाश में इंसान कभी तो डगर पे खड़ा नज़र","आता है और कभी खाई में गिर जाता है, ऐसा क्यों है?"]],[1049,["और जब तक मनुष्य समर्थ नहीं होता है, जब तक","मनुष्य में सत्य की प्रेरणा पल्लवित/पलवती","नहीं होती है,"]],[1058,["तब तक आप चाहे दुनिया का कोई सा सोशल वर्क,","पोलिटिकल वर्क, कोई सा भी बुद्धि से कर लीजिए,","उसका कोई भी ठिकाना नहीं है।"]],[1066,["आज आप आसमान में बैठेंगे कल आप नदी में डूबेंगे","क्योंकि साइंस किसी भी मनुष्य को समर्थ नहीं","बना सकता - और बना नहीं सकता है।"]],[1080,["अहंकार से मनुष्य कभी भी समर्थ नहीं","हो सकता है। सम अर्थ"]],[1091,["सो इस नतीजे पे हमको, लॉजिकल कन्क्लूशन","जिसे कहते हैं, पहुँचना चाहिए और सोचना चाहिए"]],[1098,["कि सिर्फ बुद्धि से हम सत्य को नहीं खोज","सकते हैं।"]],[1106,["बुद्धि से यह बता सकते हैं कि यहाँ सफ़ेद चद्दर","बिछी है, खादी की चद्दर है - बस और क्या?","और कहाँ तक जाएंगे हम?"]],[1121,["लेकिन क्या आप इस खादी की चद्दर में बता सकते है,","कि क्या इसे एक साधु ने पहना था या किसी राक्षस","ने पहना था?"]],[1136,["साइंस से तो आप ये भी नहीं बता सकते हैं","कि ये इंसान राक्षस है, कि मनुष्य है?"]],[1141,["और ये भी नहीं कह सकते हैं कि आज तो","मनुष्य लग रहा है कल तो भूत बनके सिर","पे सवार हो जाए तो पता नहीं।"]],[1148,["किसी चीज़ का कोई ठिकाना नहीं है, सब चीज़","चलायमान है, अस्थिर है"]],[1152,["इसीलिए आज कलयुग में कहते हैं कि पूर्णतया","मनुष्य भ्रान्ति में है, कंफ्यूशन में है।"]],[1162,["और इस कोलाहल में मनुष्य जब सोचता है कि,","\"अरे भई, ये तो आज कलयुग आ गया,"]],[1168,["अब इसमें माताजी क्या बात कर रहीं हैं? अब तो","कलयुग में ऐसा ही होता है, ये तो कलयुग है।\""]],[1174,["माने एक गारंटी हो गई हर चीज़ की। अब कलयुग","है, अब इसमें अगर ये काम नहीं करिए,"]],[1178,["तो कैसे होएगा? ये तो करना ही पड़ेगा,","ये तो कलयुग आ गया।"]],[1183,["इसमें जो है, अगर इस रस्ते से नहीं चले, तो","काम ही नहीं बनने वाला। यही रस्ता है। कलयुग है।"]],[1188,["कलयुग में आप कैसे भी मोड़ते रहिए अपने रास्ते,","किधर से भी चलिए, किसी तरह से आप दाएँ-बाएँ","घूमते रहिए, किसी तरह से आप जीते रहिए।"]],[1197,["ऐसा मनुष्य कोम्प्रोमाईज़ पे रहता है क्योंकि","स्थिर जो मूल्य थे, वो ख़त्म हो जाते हैं।"]],[1208,["जब मनुष्य भ्रांत हो जाता है उसके स्थिर","मूल्य ज़रूर ख़त्म हो जाते हैं।"]],[1213,["जब युद्ध ने ललकारा और जब यूरोपीय देशों पे","युद्ध छा गया, जब लोगों की इतनी दुर्दशा हो गई"]],[1220,["तो वहाँ के जो मूल्य थे, वो बहुत कम हो गए,","ख़त्म हो गए, करीबन ख़त्म से।"]],[1227,["क्योंकि जब सभी चीज़ डगमग डोलने लग गई,","तब लोगों को समझ ही नहीं आया कि अब","किस चीज़ को पकड़ें।"]],[1232,["इस चीज़ को पकड़ें तो ये डगडगा रही,","उस चीज़ को पकड़ें तो वह डगडगा रही।"]],[1237,["लेकिन तब ये विचार मनुष्य के मन में आना चाहिए,","कि हो सकता है कि हमने उस चीज़ को पकड़ा ही नहीं","जो स्थिर और अचल है।"]],[1245,["ऐसा मन में विचार तो उठना ही चाहिए हर एक","बुद्धिवादी के मन में ये विचार तो उठना ही चाहिए।"]],[1250,["बेटे इधर बैठ जाओ, वहाँ बड़ा ठंडा है, इधर आओ।","यहाँ पे बहुत जगह है। बाहर ठंडा है, बाहर मत बैठो।","आओ इधर बैठ जाओ। बाहर नहीं बैठो।"]],[1259,["आगे यहाँ आ के बैठ जाओ। आगे आ जाइए आप","लोग। मैं आराम से बात नहीं कर पाऊंगी अगर","सब लोग बाहर बैठेंगे।"]],[1264,["यहाँ बैठो ना। क्या हर्ज़ है? इसपे कुछ बिछा लो,","ये अच्छी चीज़ है। बाहर मत बैठो।"]],[1290,["और ये सब देखते हुए मनुष्य का मन कटुता से","भर जाता है। बड़ा कटु उसका ह्रदय हो जाता है।","वो सोचता है कि कहाँ है मिठास।"]],[1305,["कहाँ है प्यार? किसी तरह जीना है तो गृह क्या है?"]],[1315,["कोई अपना ही गला घोटता है, तो कोई","दूसरे का गला घोटता है।"]],[1321,["और इसके उत्तर में हज़ारों लोग","हज़ारों बातें बताएँगे आपसे।"]],[1326,["कोई कहेगा इसका कारण है सामाजिक अव्यवस्था,","कोई कहेगा राजकीय अव्यवस्था।"]],[1331,["कोई कहेगा कम्युनिज्म अच्छा, कोई कहेगा","कैपिटलिज़्म अच्छा, कोई कहेगा कुछ अच्छा,","कोई कहेगा कुछ अच्छा।"]],[1339,["और लोग उसको चिपक भी जाएँगे। कोई कम्युनिस्ट","हो जाएगा, तो कोई कैपिटलिस्ट हो जाएगा,"]],[1344,["कोई डेमोक्रेटिक हो जाएगा, कोई सोशियालिस्ट","हो जाएगा, तो कोई गरीब हो जाएगा,"]],[1347,["कोई अमीर हो जाएगा - मतलब कुछ ना कुछ ग्रुप","बना कर के और सोचेगा कि ग्रुप बन के जी सकते हैं।"]],[1352,["और संघर्ष, पूरी तरह संघर्ष और इस संघर्ष","में भी, चाहते क्या हैं सो उनको पता नहीं।"]],[1364,["दलित दल है, कोई है वह आतताई दल है","अनेकानेक दल बदलियाँ हो गईं।"]],[1375,["लेकिन सब आपस में हम इंसान होते हुए,","ये दल कैसे बन गए।"]],[1384,["इसके पीछे का बड़ा भारी एक रहस्य है।","और रहस्य ये है, कि उस परमपिता परमात्मा","के प्रेम को हम देख नहीं पाते हैं।"]],[1403,["हम समझ नहीं पाते हैं कि कितनी प्रेम से ये","सृष्टि उसने तैयार किया हुआ है।"]],[1410,["आप लोग तो एक बीज से एक पेड़ नहीं निकाल सकते","हैं, एक फूल से एक फल नहीं निकाल सकते हैं।"]],[1427,["आपके बस का कुछ भी नहीं। ज़रा सोचिए,","कितना परमात्मा ने हमें सौंदर्य दिया हुआ है।"]],[1438,["और कितना कुछ हमारे लिए कर दिया है।"]],[1444,["इस आदमी ने ये भुला कर के कि जिसने हमें बनाया,","इतना बड़ा किया - एक अमीबा से इंसान बना दिया"]],[1454,["उसके प्रति कोई भी कृतज्ञता नहीं है, उधर कोई","भी चित्त नहीं है, उधर कोई भी विचार नहीं है।"]],[1464,["इसलिए अधूरापन आ गया है। और जो कुछ कह","गए लोग, जो कुछ बता गए, उनको या तो जिन्होंने","माना, वह गलत तरीके से मान लिया"]],[1474,["उसकी भी दल-बंधियाँ बना लीं और कुछ लोगों ने","कहा कि, ये तो सब ऐसी ही बातें हैं, इसमें कोई","अर्थ नहीं है - सब झूठ है।"]],[1487,["ऐसी सब दशा में कि जब मनुष्य एकदम निराश","और हताश है, और कटुता से भरा हुआ है,"]],[1495,["और उसकी नज़र में परमात्मा का प्रेम ही","नहीं झलकता है"]],[1499,["अभी मेरे सामने देखिए, कोहरे में से थोड़े-थोड़े से","ये पत्ते दिखाई दे रहे हैं - कितना सुन्दर बना हुआ है सब"]],[1507,["इसका आनंद अंदर झरा जा रहा है। और ये सब","सृष्टि का सौंदर्य भी हमारे आँख से ओझल हो गया"]],[1517,["और हम एक बड़ी बोझिल ज़िन्दगी से दबे हुए हैं,","तब समझ में नहीं आता, कि ऐसा क्यों?"]],[1527,["अगर परमात्मा ने अपने प्रेम से हमें बनाया, संजो","कर बनाया, इतने आनंद से उसने ये सृष्टि रची है,"]],[1535,["तो आखिर हम इतने बड़े आफत में क्यों फंस गए?"]],[1544,["इसका कारण ये, कि हमने खुद ही अपनी","गर्दन कटा ली है।"]],[1553,["गर्दन कटाना - सहज योग में जिसे कि विशुद्धि","चक्र कहते हैं, जिसमें विराट का स्थान है,"]],[1563,["गर्दन कटाने का मतलब होता है, कि आपने","विराट से अपना सम्बन्ध तोड़ दिया -"]],[1568,["उस बड़े विराट से जिसके हम अंग-प्रत्यंग हैं,","जो परमात्मा के नाम से जाना जाता है, उससे","ही हमने अपना रिश्ता तोड़ लिया है।"]],[1580,["और बहक गए हैं अपने ही दिशा में, और अपने","ही विचारों में, और अपने ख्यालों में,"]],[1587,["सोच कर के कि ये चीज़ ही सही है, और बाकी","जितनी भी चीज़ें हैं, वह गलत हैं।"]],[1596,["इस मोड़ पर ही आज सहज योग, एक महायोग","के रूप में, आपके सामने आया हुआ है।"]],[1607,["इसको सोच-विचारने से आप जान नहीं सकते, क्योंकि","मैंने पहले ही कहा, कि सोच-विचारने से, आपसे","जो निम्न चीज़ है वो पाई जाएगी।"]],[1615,["आपसे जो ऊँची चीज़ है, ये आपकी कल्पना की भरारी","है। कल्पना से आप सोच सकते हैं, कि हम आकाश में","घूम रहे हैं, कुछ भी, लेकिन वो यथार्थ नहीं है।"]],[1626,["वो यथार्थ नहीं है, रिऐलिटी नहीं है, यथार्थ नहीं है।","ये मान लेना चाहिए, कि जो कुछ भी हम सोचते बैठते","रहते हैं, कि हम फलाने हैं और ढिकाने हैं,"]],[1635,["और ऐसा होगा, वैसा होगा, यथार्थ नहीं है। तब तो ये","समझ लेना चाहिए कि जो यथार्थ में हमने पाया"]],[1644,["वो अपने से निम्न ही पाया, और अपने से जो ऊँचा","पाना है, उसके लिए यथार्थ में कोई चीज़ होनी चाहिए।"]],[1654,["और यथार्थ में क्या होना चाहिए, इसका भी","विचार उस बनाने वाले ने कर दिया है।"]],[1661,["वो ही इसको करने वाला है। उसका भी विचार है,","जिसने आपको ये आँखें, नाक, मुँह, सब कुछ,","शरीर दिया है,"]],[1670,["मन, बुद्धि, अहंकार, आदि सब चीज़ें आपके अंदर दीं हैं,","वही आपको वो भी खूँटी दे देगा, जिसमें पहुँच कर","आप इससे ऊँची दशा में आ जाएँ।"]],[1683,["उसने भी ये सोच कर ही आपको मनुष्य बनाया है।"]],[1688,["लेकिन सबसे पहले तो बुद्धि जीवी को सोचना","चाहिए कि ये बुद्धि कहाँ तक पहुँचती है।"]],[1693,["ये कितनी सीमित चीज़ है, और जब असीम की बात हो","रही है, तब बुद्धि का बीच में रगड़ना ठीक नहीं है।"]],[1705,["इस असीम को जानने के बाद, पहचानने के बाद,","जैसे नानक साहब ने कहा है 'चीन्हने के बाद'"]],[1717,["तब आप ये समझ सकते हैं, कि आप क्या हैं,","आप क्यों इस संसार में आये हैं,"]],[1726,["और ये जो सर्वव्यापी परमात्मा की जीवंत शक्ति है,","ये कौन से कार्य को करती है, और कैसे करती है।"]],[1734,["इतना ही नहीं, जब आपके अंदर आत्मा का साक्षात्कार","हो जाता है, तब ये शक्ति आपके अंदर से बहती है","और कार्यान्वित होती है।"]],[1744,["आप इस शब्द पे ज़रूर नज़र करें। ये शक्ति बोलती","नहीं, सोचती नहीं है, कार्य करती है,","कार्यान्वित होती है।"]],[1758,["बोलना और सोचने का काम तो बुद्धि का है -","निरर्थक - इससे कोई कार्य थोड़ी होता है।"]],[1763,["जैसे मोटर में बैठिए आप और सोचने लग","जाईए - क्या मोटर चलेगी आपकी?"]],[1769,["कुछ करना होता है। लेकिन ये शक्ति ऐसी है कि जब","आपके अंदर से बहने लगती है, तो कार्यान्वित होती है।"]],[1779,["कार्य करती है। जैसे प्रकाश है, कार्यान्वित है। जब","उसमें से प्रकाश आ रहा है, तो प्रकाश दिख रहा है।"]],[1785,["कार्य कर रहा है, ऑटोमैटिक है। न कुछ करते","हुए भी प्रकाश, प्रकाश दे रहा है।"]],[1793,["उसी प्रकार, ऐसा इंसान कुछ न करते हुए भी,","प्रकाश दे सकता है और कार्यान्वित है।"]],[1804,["इस बात को, मेरे ख्याल से, यूनिवर्सिटी में इसलिए","कही गई है, क्योंकि यूनिवर्सिटी का मतलब ही","होता है, विश्वव्यापी।"]],[1813,["लेकिन बुद्धि विश्वव्यापी नहीं हो सकती है।","अगर होती तो अभी तक हो गई होती।"]],[1819,["हर एक की बुद्धि तो वहीँ-वहीँ चलती है।","एक की दूसरे से मेल नहीं बैठता।"]],[1830,["तो इस चीज़ को पाने के लिए सबसे पहले","नम्रतापूर्वक ये स्वीकार करना चाहिए"]],[1836,["कि अभी तक हमने जो कुछ जाना है, वो सीमित है","और असीम को जानने के लिए कोई न कोई घटना","हमारे अंदर घटित होनी चाहिए,"]],[1848,["कोई न कोई अंकुर हमारे अंदर जागना चाहिए,","जिससे हम जो आज ऐसे सीमित से लग रहे हैं,","वो आकाश बन कर के छा जाएँ सब।"]],[1860,["बड़ों ने समझाने के लिए बहुत तरीके से कहा","है, कि बूँद को सागर होना चाहिए।"]],[1867,["अब सब सिमीलीज़ भी जो हैं, ऐनालॉजीज़ भी","जो है, वो भी निम्न चीज़ों से ही हैं। ये तो","एक बड़ा भारी प्रश्न है।"]],[1876,["कि वो भी कहाँ से लाएँ क्योंकि ऊँची चीज़ की तो","बात ही नहीं कर सकते और जो ऐनालॉजी करते","हैं, वो नीची चीज़ की करेंगे"]],[1883,["और जो भी नीची चीज़ की करेंगे, वो आपको और","नीचे की तरफ खसकाती जाएगी।"]],[1888,["जैसे ही कहा कि, 'आप बूँद से सागर हो जाईए,'","वो कहेंगे, 'साहब बूँद से सागर कैसे हो सकते हैं?'"]],[1898,["कितने भी गोल घुमाकर के बात समझाई जाए,","समझ में नहीं आएगी, क्योंकि समझने वाला","जो है, वो ये बुद्धि का ही प्रकार है।"]],[1907,["जब समझना आत्मा से ही हो सकता है, तब बुद्धि","से क्या समझाया जा सकता है, आप ही बताइए।"]],[1916,["जैसे कि हमारे यहाँ बहुत से विदेशी सहज योगी","आये हुए हैं। ये आपके संगीत के बारे में","'सा, रे, ग, म,' भी नहीं जानते।"]],[1926,["अपने संगीत के बारे में सब जानते हैं। आपके संगीत","शास्त्र के बारे में कुछ नहीं जानते हैं। राग-रागिनियों","के नाम नहीं जानते हैं।"]],[1935,["लेकिन अगर कोई सा भी हिंदुस्तानी शास्त्रीय संगीत","शुद्ध बजाया जाए, तो कितना भी कठिन राग हो,","उसमें मस्त हो जाते हैं।"]],[1945,["उसका वो राग नहीं खोजते, उसकी आलापकारी नहीं","देखते, पर उसका जो असर है, उसका जो कार्य है,","उनके अंदर बन जाता है।"]],[1956,["नहीं तो अगर अपने हिंदुस्तानी सुनने बैठेंगे, तो","पहले पूछेंगे, \"साहब गाने वाली कौन है?\""]],[1964,["फिर, 'ये राग कौन सा है,' विचार आ गया बीच में।","इनका घराना कौन सा है, इनके बाप-दादे कौन से हैं,","ये ठेका कौन सा लग रहा है,'"]],[1974,["लेकिन जो इस चीज़ पे बैठा नहीं है, वो सिर्फ","अपने आत्मा से उसका अनुभव ले रहा है,"]],[1980,["उसका मज़ा ले रहा है, और वो राग जिस चीज़ के लिए","बनाया गया था, वो आनंद, पूरा के पूरा उस आदमी में","उसमें समाया जा रहा है।"]],[1989,["जिस आनंद से वो बनाया गया था, वही पूरा की","पूरा आनंद उसमें समाये जा रहा है और उसमें","कार्यान्वित है।"]],[1999,["इस आनंद की प्राप्ति आप सब को हो सकती है","- ये हमारा है। आप अगर कहें, तो हम भी","इस बात को मान जाएँ।"]],[2011,["अगर आप कहें, कि हम हीं क्यों ये काम कर रहे","हैं, तो हम कहें आप करिए, बहुत अच्छा है,","आप ज़रूर करिए।"]],[2018,["हमें, तो हम बड़े खुश हैं, कि आप लोग कर लें","तो बड़ा अच्छा है - कोई भी कर ले।"]],[2022,["इससे बढ़के और कौन सी बात हो सकती है, कि भई","हमारे जगह और कोई काम कर ले, ये तो बहुत","अच्छी चीज़ है।"]],[2027,["लेकिन ये है, कि इस काम के लिए शायद, हमीं","को करना पड़ेगा, कुछ दिनों तक तो।"]],[2034,["अगर आप से हो सकता है, तो आप करिए।"]],[2037,["काम है जटिल, प्रेम का काम है।","और प्रेम सत्य है और सत्य प्रेम।"]],[2049,["इतना गहन प्रेम है ये, कि इसमें मनुष्य फ़ौरन","पहचान जाता है, कि दूसरों को क्या शिकायत है।"]],[2059,["दूसरा कोई रह ही नहीं जाता है, इतना गहन प्रेम","है ये। सब अपने अंग-प्रत्यंग हो गए।"]],[2066,["जब दूसरा कोई नहीं रहा, तो किस पे","उपकार करने जा रहे हैं आप।"]],[2075,["और जब ये प्रेम किसी पे भी प्रकाशित होता है,","तो सारा सत्य उस आदमी का, पूरा का पूरा,","सामने नज़र आ जाता है।"]],[2087,["पूरी की पूरी चीज़, पूरी तस्वीर सामने आ जाती है।","उस प्रकाश में आप जान लेते हैं,"]],[2095,["कि ये जो आपका अंग-प्रत्यंग है, इसमें क्या","तकलीफ है। कार्यान्वित है।"]],[2101,["प्रकाश से प्रकाश में आपको दिखना चाहिए, साफ़-साफ़","नज़र आना चाहिए उसमें गलती नहीं होनी चाहिए।"]],[2107,["एक ही नहीं, सब लोग जो देखेंगे, वो एक ही बात","कहेंगे, कि माँ ने सफ़ेद रंग की साड़ी पहनी है।"]],[2116,["उसमें अनेक विचार नहीं हो सकते हैं, उसमें झगडे","की बात नहीं हो सकती है। एक ही सत्य हो सकता है"]],[2129,["और जो एक ही सत्य होता है, वो अनेक होते","हुए भी, एक ही जैसा दिखता है।"]],[2139,["लेकिन इस प्रेम को आज तक किसी ने जाना नहीं।","बहुत थोड़ों ने जाना, और जिन्होंने जाना, उनसे","किसी ने जानना नहीं चाहा।"]],[2147,["उनको परेशान किया, उनको सताया और उनके मरने","के बाद मंदिर खड़े कर दिए, चर्च खड़े कर दिए,"]],[2154,["और दुनिया भर के गुरूद्वारे खड़े कर दिए, और सब","चीज़ खडी कर दी, लेकिन उस प्रेम को नहीं जाना,","जिस प्रेम के सहारे ये सब चीज़ें खड़ीं हैं।"]],[2167,["उस प्रेम को जानने के लिए भी आत्मा का ही","अवलम्बन करना पड़ेगा।"]],[2175,["जैसे लौकिक चीज़ें जानने के लिए हम बुद्धि का","अवलम्बन करते हैं, वैसे ही अलौकिक चीज़ें जानने के","लिए हमें आत्मा का अवलम्बन करना पड़ता है।"]],[2187,["अब कोई कहेगा आत्मा है या नहीं? पहले ही","झगड़ा क्यों ले के बैठ गए? पहले ही से","इसका ऊहापोह क्यों है?"]],[2200,["भई देखो, है या नहीं। अब तो हम","सिद्ध करने आये हैं।"]],[2206,["पहले के लोगों को आप कह सकते थे, कि वो सच थे,","कि झूठ थे - उनके बारे में आप पचासों बातें कहिए।"]],[2214,["लेकिन अब तो हम आपको सिद्ध करने आये हैं,","कि आपके अंदर आत्मा का स्थान है"]],[2220,["और परमात्मा, सर्वव्यापी, अपने साम्राज्य","में आपको आमंत्रित करता है।"]],[2230,["ये सर्वव्यापी शक्ति उस परमपिता परमात्मा","की प्रेम की लहर है।"]],[2240,["उसका आनंद देने के लिए ही, परमात्मा ने आपको","इंसान बनाया है। अहंकार से मनुष्य को सुख हो","सकता है, आनंद नहीं हो सकता है।"]],[2252,["सुख के बाद दुःख भी हो सकता है, लेकिन आनंद","में सुख और दुःख दोनों भावनाएं टूट कर के","एकमात्र आनंद होता है,"]],[2262,["जिसको शब्दों में वर्णन नहीं करा जा सकता है,","सिर्फ अनुभव किया जा सकता है।"]],[2267,["लेकिन उसका अनुभव भी इस ह्रदय से नहीं है","जिसको आप ह्रदय कहते हैं।"]],[2275,["इसको ह्रदय नहीं कहना चाहिए क्योंकि अगर ये","ह्रदय है, तो ये तो कभी रुलाता है, कभी हंसाता है।"]],[2285,["हृद जो जाने, वो आत्मा है। रि शब्द से, रि का मतलब","है एनर्जी। र र रा रा माने एनर्जी, शक्ति। इस प्रेम की","शक्ति को जो देने वाला है, वो हृद।"]],[2306,["इसलिए वो प्रेम की शक्ति को देने वाला, या","जानने वाला, ये आत्मा जो है, इसको पाना चाहिए।"]],[2318,["इतने तक अगर आप सब बुद्धिवादी उतर आयें,","तो फिर आगे की बात हम कह सकते हैं।"]],[2327,["इतने तक पहले उतर आईए - ये बहुत ज़रूरी चीज़ है।","क्योंकि नहीं तो बीच ही में आपकी बुद्धि खड़ी हो गई"]],[2334,["कि, \"पर माताजी, इसका ऐसे कैसे।\" बुद्धि के सतह पर","इस बात का जवाब कुछ भी दें, आप संतुष्ट नहीं","हो सकते,"]],[2345,["क्योंकि वो संपूर्ण जवाब हो नहीं सकेगा। हालाँ","लोजिकली मैं आपको ले आई हूँ उस पॉइंट पे","जहाँ आप ये कहेंगे कि,"]],[2353,["\"अच्छा तो माँ बताओ, ये आत्मा कैसे पाया जाए?\"","मुझे आशा है, कि ये आप लोगों के सबके अंदर"]],[2360,["ऐसी भावना शायद हो गई हो, कि माँ जो कह","रही है, उसमें कुछ सच्चाई भी है।"]],[2369,["अब आपने फ़रमाया कि अंग्रेजी में बात करें, तो कोई","अगर आप सवाल आप पूछें, तो अंग्रेजी में जवाब","दे देंगे।"]],[2402,["करिए प्रश्न करिए कुछ भी, आप लोग तो","बहुत विद्वान हैं।"]],[2418,["सहज योगी : आत्मा क्या है? आत्मा क्या है?"]],[2423,["श्री माताजी: क्या कह रहे हैं?","सहज योगी: आत्मा क्या है?"]],[2427,["श्री माताजी: आत्मा उस परमात्मा की परछाईं है।","आत्मा उस परमात्मा का प्रतिबिम्ब है, जो इस मानव","में दृष्टिगोचर हो सकता है।"]],[2441,["रिफ्लेक्शन है। यह परमपिता परमेश्वर","का प्रतिबिम्ब है हमारे ह्रदय में। अगर ह्रदय","एक अच्छा ..."]],[2454,["हाँ, यह बेहतर है। ज़रा सा गुनगुना हो तो","पी लेंगे। चाय नहीं।"]],[2460,["यदि ह्रदय स्वच्छ है, एक स्वच्छ","दर्पण की भांति, तो प्रतिबिंब सबसे अच्छा है।"]],[2467,["यह साधारण सी बात है, हमारे भीतर","सर्वशक्तिमान ईश्वर का प्रतिबिंब है।"]],[2475,["साधक: माँ आप ये बताइये, कि कुण्डलिनी","और आत्मा डिफरेंट (भिन्न) चीज़ें हैं दोनों।","श्री माताजी: अच्छा बेटे, बैठो।"]],[2482,["श्री माताजी: इन्होंने मुझसे एक सवाल पूछा है","- अंग्रेज़ी में बताऊँ, बेटा"]],[2487,["साधक: हिंदी में बताइये।","श्री माताजी: हिंदी में, अच्छा।"]],[2491,["इन्होंने पूछा है कि, कुण्डलिनी और आत्मा में क्या","सम्बन्ध है? अब पहले मैंने बताया आपसे, कि","परमात्मा का प्रतिबिम्ब जो है, वो आत्मा है।"]],[2506,["एक बात हो गई। और परमात्मा की जो शक्ति है,","उसे आदिशक्ति कहते हैं, होली घोस्ट कहते हैं,","या चाहिए तो उसको आप उसे रूह कहिए।"]],[2520,["इस शक्ति का प्रतिबिम्ब जो मनुष्य में होता","है, वो कुण्डलिनी है।"]],[2527,["जब तक ये दोनो चीज़ मिलती नहीं, तब योग","घटित नहीं होता। योग माने यूनियन (जुड़ना)।"]],[2537,["और जैसे ही ये चीज़ घटित हो जाती है,","तो जैसे कि समझ लीजिए,"]],[2547,["ये एक बहुत ही ग्रोस तरीके से फिर ऐनलॉजी","बताएँगे, कि जो बिल्कुल निम्न चीज़ है उसकी -"]],[2552,["कि जैसे इसकी जो कनेक्शन है जैसे ही मेन्स से लग","जाता है, तो जो प्लग है उसमें इसको लगा देने से ही,","इसका कनेक्शन चल जाता है।"]],[2567,["तो इसमें कहिए कि कुण्डलिनी ये है,","और प्लग जो है वो आत्मा है।"]],[2576,["अब है बहुत ग्रॉस चीज़ लेकिन करें क्या। कोई सी भी","ऐनालॉजी दीजिए, कितनी भी काव्यमय बनाइये,","तो भी वो निम्न तो होगी ही।"]],[2588,["इतना निकट सम्बन्ध है एक दूसरे में।"]],[2595,["उन्होंने मुझसे प्रश्न पूछा, कि आत्मा और","कुंडलिनी के बीच में क्या संबंध है?"]],[2602,["मैंने बताया, मैं उन्हें हिंदी भाषा में एक तर्क","बता रही थी, कि हमें जो कुछ भी हासिल","करना है, या हम हासिल करते हैं,"]],[2614,["या हम वर्णन करते हैं, या बात करते हैं, वह हमसे नीचे","है - हमसे ऊपर नहीं है, क्योंकि यह हमारी बुद्धि या","हमारी भावनाओं के माध्यम से होता है।"]],[2629,["इसलिए यह हमसे ऊँचा नहीं है, वह पूरी चीज","हमसे नीचे है, जिसे हम संभाल सकते हैं।"]],[2636,["कल्पना में आप कुछ बड़ी चीजों, उच्च चीजों के","बारे में सोच सकते हैं, लेकिन यह कल्पना","वास्तविकता नहीं है।"]],[2643,["तो वास्तव में जब आपको किसी चीज़ से","निपटना होता है, वास्तव में"]],[2649,["तब आप उन चीजों से निपटते हैं जो","आपसे नीचे हैं।"]],[2657,["इसलिए बहुत से लोग कहते हैं कि,","\"माँ, आप व्यावहारिक नहीं हैं।\""]],[2663,["बहुत से लोग कहते हैं कि, \"माँ, आप व्यावहारिक","नहीं हैं,\" क्योंकि उन्हें ऐसा लगता है"]],[2668,["कि मेरा चीजों के प्रति बहुत अव्यावहारिक रवैया है,","क्योंकि मुझे निचली चीजों से निपटना चाहिए।"]],[2675,["जैसा कि मैंने बंबई में कहा था कि, \"मैं कोई काला धन","या कुछ भी नहीं दूँगी। अगर मुझे जमीन नहीं मिली","तो कोई बात नहीं।\""]],[2682,["इसलिए उन्होंने सोचा कि मैं अव्यवहारिक थी।","मुझे कहना चाहिए कि आप उन्हें भुगतान करें?"]],[2687,["भगवान की कृपा से किसी आदमी ने हमें, बिना","एक पाई दिए, एक एकड़ जमीन दान में दे दी।"]],[2698,["सहज योगी: एक और प्रश्न है माँ। मनुष्य को","अँधेरे से डर क्यों लगता है?"]],[2704,["श्री माताजी: सब मनुष्यों को नहीं लगता है।"]],[2708,["एक सवाल है - कि कुछ पुरुष अंधेरे से क्यों डरते हैं?","सब नहीं.... अँधेरा कभी-कभी कुछ आदमियों से","डरता है।"]],[2723,["ये बात सही नहीं। प्रश्न जो है, अधूरा है बेटा। लेकिन","डर इसलिए लगता है अँधेरे से - वही बात आ गई ना,","कि अदृश्य से इंसान डरता है।"]],[2735,["और अँधेरे में जो जो गड़बड़ी इंसान ने की इंसान","के ऊपर में, इसीसे वो डरता है।"]],[2740,["और भी बहुत सारी बातें हैं, पर ख़ास बात ये है","कि, इंसान के अंदर जब अँधेरा होता है, तब","उसे ज़्यादा डर लगता है।"]],[2749,["जब वो प्रकाश में आ जाता है, उसको अँधेरा और","उससे कभी डर नहीं लगता है।"]],[2755,["अंदर में अँधेरा है, बाहर अँधेरा है, तो बहुत","ही ज़्यादा अँधेरा हो जाता है। मनुष्य घबड़ा जाता है।"]],[2762,["'कि बाबा रे बाबा, रास्ता तो ऐसे ही नहीं","मिल रहा ऊपर से अँधेरा।'"]],[2769,["लेकिन जब अंदर प्रकाश हो जाता है, तो बाह्य","के अँधेरे कोई दिखाई नहीं देते।"]],[2776,["अभी अँधेरा है, आप सोचते हैं, और मैं इसमें","भी बड़ी सुन्दर चीज़ें देख रहीं हूँ।"]],[2783,["साधक: ये जो इतने बड़े-बड़े विश्वविद्यालय हैं","अपने देश के अंदर और बहार भी, और इसमें इतना","धन भी खर्च करती है सरकार"]],[2792,["और बाकी सब लोग मिलकर भी और इतने-इतने","विद्यार्थी उसमें लगे हैं जो दिनों रात उसमें","परिश्रम करके"]],[2798,["कुछ प्राप्त करते हैं। आपके हिसाब से","मानो वो छोटा सा लोअर स्तर का है?"]],[2802,["श्री माताजी: बिलकुल।","साधक: तो क्या, ये जो आपने व्यवस्था बनाई,"]],[2805,["उसकी व्यवस्था के लिए कोई ऐसी व्यवस्था","वो हो, नहीं दी जा सकती?"]],[2809,["जैसे मान लो कोई जिज्ञासु हों, जानने की इच्छा हो,","न भी हो तो जिज्ञासा उसके अंदर पैदा की जाए"]],[2815,["और उस तरफ भी लोगों को मोड़ देने के लिए,","कुछ आश्रम पद्यति या इस टाइप की जो पहले","बताते थे, वैसी व्यवस्था हो"]],[2822,["श्री माताजी: उसी की तो हालत बता रहीं हूँ,","कि वो आश्रम के लिए ज़मीन लेने गए, तो वो कहने","लगे, \"ब्लैक मनी दो।\""]],[2827,["फिर कहने लग गए, तुम ब्राइब (घूस) दे दो -","करते-करते १२ साल तो बीत गए। अब एक साहब","ने ज़मीन दे दी।"]],[2833,["आपके यहाँ प्रेजिडेंट साहब ने हमें ज़मीन दी,","क्योंकि उनको हमने ठीक किया था। तो उन्होंने हमको","दे दी सब्ज़ी मंडी में जहाँ बैल बैठते हैं।"]],[2843,["सही बात है। आप जाके पूछ लीजिए। अजीब-अजीब","पागल लोग दुनिया में घूमते हैं, बताईये।"]],[2848,["अब सब्ज़ी मंडी में दे दी। अभी इसको भी चार साल","बीत गए। सब्ज़ी मंडी से फिर इधर ले गए, फिर उधर","ले गए, फिर उधर ले गए, यही चल रहा है।"]],[2857,["जब तक मनुष्य की बुद्धि ठीक नहीं होती है, तब","तक आश्रम भी नहीं बनने वाले मेरे ख्याल से।"]],[2863,["आश्रम तभी बन सकते हैं, जब आदमी सोचे भी कि","इसकी ज़रुरत है। नहीं तो यहाँ वीरान यूनिवर्सिटीज","बन जाएँगी और कोई उसमें आएगा ही नहीं।"]],[2871,["इसलिए पहले थोड़ा आदमी के दिमाग में ठनकना","चाहिए। उसकी ठनक ज़रूर बैठनी चाहिए ,"]],[2876,["और इसीलिए, कलयुग जो है इसी में ठंकेगा आदमी,","नहीं तो उसके दिमाग में आने नहीं वाली बात।"]],[2882,["ऐसे समझाने से समझने नहीं वाले। आप बताइए","आज यहाँ पर आप इतने लोग बैठे हैं,"]],[2887,["इस यूनिवर्सिटी के कितने सुविद्ये यहाँ बैठे हुए हैं,","मतलब, प्रोफेसर्स नहीं लेकिन लड़के कॉलेज","के बैठे हैं कोई"]],[2897,["देख लीजिए, है कोई - एक, दो, तीन, चार, पाँच, बस","छः - छह बच्चे बैठे हैं - अब आप ही बताइए?"]],[2908,["अब क्या करूँ मैं? इस यूनिवर्सिटी, यहाँ मैं","दिल्ली यूनिवर्सिटी मैं कितने सालों से आ रहीं हूँ,","मैं आपसे बताऊँ - करीबन 11-12 सालों से।"]],[2917,["बारह साल में आज छह बच्चे मिले हैं, अब बोलिए?","इसे हम क्या करें बेटा, हम तो अपनी तरफ से","बड़ी मेहनत कर रहे हैं।"]],[2927,["रातों-दिन एक कर दिया लेकिन यहाँ कोई इधर","आता ही नहीं। फिर वो दिल्ली यूनिवर्सिटी","हुई, तो और भी हालत खराब है।"]],[2943,["और वो जो आपकी जवाहरलाल नेहरू यूनिवर्सिटी","है, उसमें तो एक इंसान आया मेरा भाषण सुनने।"]],[2949,["मैंने तो दीवारों को ही भाषण दिया बस।","ज़रुरत तो नितांत है।"]],[2958,["जब तक ये लोग बहुत आफत में नहीं फँसने वाले,","तब तक इनकी अकल नहीं ठिकाने आएगी।"]],[2965,["जैसे परदेस में हमारा ज़्यादा काम हो रहा है। कैंब्रिज","यूनिवर्सिटी में, न्यू यॉर्क यूनिवर्सिटी में, कनाडा में"]],[2972,["- तीन जगह हमारे थीसिस लोग लिख रहे हैं","सहज योग पर। सहज योग के बारे में","थीसिस लिखा जा रहा है।"]],[2983,["आप देहली यूनिवर्सिटी में कोई करेगा ऐसा काम?","कोई मानेगा यहाँ पर, कि सहज योग पर","एक थीसिस लिखा जाए।"]],[2991,["और अगर लिखेंगे, तो भी ऐसा, इतना सुपरफिशिअल","कि उससे सहज योग का काम ही रुक जाए","परमानेंट।"]],[2999,["वो यही कह देंगे कि माताजी जो हैं वो सफ़ेद ही","साडी पहन कर बैठतीं हैं, या उनका फलाना ही","है, तो ढिकाना है,"]],[3007,["कुछ भी, जो अपने मन से जो भी वो सुपरफिशिअल","समझें, वो बात कह देंगे, जैसे अखबारी चीज़ें चलतीं हैं।"]],[3013,["तो ज़रा से यहाँ के लोगों को थोड़ी सी","ठनक बैठने की ज़रुरत है।"]],[3017,["उसके बगैर इनकी अकल नहीं दुरुस्त होने वाली,","ऐसा ही मुझे लगता है।"]],[3022,["बारह साल से मैं यहाँ आ रहीं हूँ बेटे, तब ये","हालत है। इससे आप समझ लीजिए।"]],[3028,["अब आप इसी से समझ लीजिए कि मैंने","मेरी मेहनत में कमीं नहीं करी।"]],[3034,["और यहाँ पर ऐसे भी बहुत से हैं कि जो पार हो गए हैं।","परदेस से आए हुए भी 130 लोग यहाँ बैठे हुए हैं।"]],[3042,["उतने ही इधर के बैठे हैं। अगर परदेस से","नहीं आएं, तो यह जगह भी नहीं भरती।"]],[3049,["सच्ची बात है। मैं क्या करूँ? लोगों को रूचि ही","नहीं है, इधर विचार ही नहीं है। वो तो सोचते हैं","कि बड़े अफ़लातून हो गए। क्या कहा जाए।"]],[3066,["सहज योगी: एक सज्जन हैं जो लिखते हैं, माँ, \"मैं मूलाधार और सहस्त्रार चक्र पर तथा","कुंडलिनी के जागरण पर आपके व्याख्यान में","शामिल होने में असफल रहा।"]],[3075,["साधक: टेप रिकॉर्डर द्वारा इसे सीखने की मेरी तीव्र","इच्छा है और मैं इस महीने की 2 या 3 तारीख तक","अपने मूल स्थान के लिए रवाना हो रहा हूँ।"]],[3084,["श्री माताजी: कौन है?","सहज योगी: कोई हैं साहब।"]],[3087,["श्री माताजी: यह सज्जन कौन है? ठीक है। एक","व्यवस्था है, कि आप मेरे व्याख्यान ले सकते हैं, जो","टेप किए गए हैं और आप वहाँ से ले सकते हैं। ठीक है?"]],[3102,["लेकिन देखिए, अगर आपको अपना बोध नहीं प्राप्त","है, तो मेरे व्याख्यान किसी काम के नहीं हैं।"]],[3108,["यह एक अच्छी बात है, आप देखते हैं, क्योंकि","माँ अच्छा बोलतीं हैं, आप देखते हैं, वह बोलने","में अच्छीं हैं,"]],[3114,["उन्हें सुनने में बहुत अच्छा लगता है लेकिन","आपको पहले अपना आत्मसाक्षात्कार प्राप्त","होना चाहिए, ठीक है?"]],[3120,["साधक: (अस्पष्ट - लिया है?)","श्री माताजी: आपको प्राप्त हो गया?","फिर तुम ले लो।"]],[3122,["तब तुम इसे ले लो, तब तुम मेरे पुत्र हो।","ठीक है? जो तुम्हे चाहिए तुम ले लो।"]],[3130,["सहज योगी: यही साहब लिखते हैं, \"धर्म और योग में","अपने 30 वर्षों के अनुभव के दौरान मैंने ऐसा"]],[3136,["प्रतिष्ठित व्यक्ति नहीं देखा है जिसे कुंडलिनी का","इतना विशाल ज्ञान हो। दिल्ली छोड़ने से पहले"]],[3143,["मैं सहज योग उपचार और तकनीक के बारे में","और जानना चाहता हूँ। मैं पिछले दिसंबर में","दिल्ली आया था।\""]],[3150,["श्री माताजी: ये किसके पास गए थे?","सहज योगी: किसके पास गए थे आप पहले?"]],[3156,["श्री माताजी: कौन से एमिनेंट पर्सन के पास गए थे?","साधक: माताजी"]],[3161,["श्री माताजी: हैं?","साधक: आपके ही पास, माताजी"]],[3164,["श्री माताजी: हैं? माताजी कौन?","साधक: आपके पास गए।"]],[3167,["साधक: आपका बता रहे सर, आपसे ही सीखा हैं।","श्री माताजी: मुझसे सीखा था आपने?"]],[3170,["साधक: जी हाँ","श्री माताजी: आपने मुझसे सीखा था?","साधक: हाँ जी।"]],[3173,["श्री माताजी: फिर तो ठीक है।","सहज योगी : यह धर्म और योग में 30 वर्ष के","अनुभव की बात कर रहे हैं।"]],[3178,["श्री माताजी : 30 वर्षों का अनुभव कैसे हुआ फिर? हैं?","मैंने तो अपना काम सिर्फ12 वर्ष पहले शुरू किया है।"]],[3189,["सहज योगी : ओवरटाइम किया इसने।","श्री माताजी : ठीक है। लेकिन बेहतर होगा कि","आप टेप रिकॉर्डर ले लें।"]],[3196,["भले ही आपको आज ही आत्मसाक्षात्कार प्राप्त हुआ","हो, आप उसे ले सकते हैं, ठीक है? बस इतना ही।"]],[3201,["आप देखें, क्योंकि आत्म-साक्षात्कार के बिना","यह आपके हाथों में सिर्फ एक उपकरण है,"]],[3205,["लेकिन आत्म-साक्षात्कार के बाद यह आपके","हाथों में एक प्रकाश है। उसको दे देना।"]],[3211,["तुम इसे ले सकते हो। जो लोग मेरे टेप लेना","चाहते हैं, वे ले सकते हैं"]],[3216,["लेकिन आपको एक आत्मसाक्षात्कारी बनना होगा,","अन्यथा हम नहीं देते क्योंकि इस सस्ती लोकप्रियता","का क्या फायदा?"]],[3224,["सहज योग के बारे में सस्ती लोकप्रियता की","कोई आवश्यकता नहीं है - आपको बनना होगा।"]],[3230,["यहाँ आप सिर्फ एक सदस्य नहीं हो सकते, हमारी","कोई सदस्यता नहीं है, कुछ भी नहीं -","यह एक जीवित जीव है।"]],[3236,["इसलिए, यदि आप बनते हैं, तो आपका हर अधिकार","है, लेकिन यदि आप नहीं बनते, तो आपका","कोई अधिकार नहीं है।"]],[3243,["जैसे कि, आपको इस देश में कुछ अधिकार प्राप्त करने","के लिए एक भारतीय नागरिक होना चाहिए - मुझे","आश्चर्य है कि क्या हमारे पास कोई है।"]],[3252,["लेकिन यहाँ भगवान के राज्य में, अगर आप इसमें","प्रवेश करते हैं, तो आपके पास सभी अधिकार हैं"]],[3263,["और वह हर समर्थन के साथ, हर मदद के साथ,","आपकी देखभाल करते हैं, यहाँ तक कि आपको","लगता है,"]],[3270,["कि अब चमत्कार अपना अर्थ खो चुके हैं","- हर कदम अचंभित हो जाएँगे।"]],[3282,["सहज योगी: वही व्यक्ति ने पूछा है","कि अनिद्रा का इलाज कैसे करें?"]],[3286,["श्री माताजी: क्या मारो?","सहज योगी: अनिद्रा","श्री माताजी: अनिद्रा"]],[3289,["सहज योगी: लेकिन वह कहते हैं, कि पिछली बार हिंदी","के 50% ज्ञान के कारण, उन्हें समझ में नहीं आया।"]],[3293,["श्री माताजी: अनिद्रा पूरी तरह से सुसाध्य","(ठीक हो जाती) है। यदि आपने इससे पहले मेरे","व्याख्यानों में भाग लिया है,"]],[3300,["तो मैंने आपको बताया कि अपने आप को कैसे","संतुलित कर सकते हैं लेकिन फिर भी"]],[3304,["आप केंद्र में आएं और वे लोग आपको बताएंगे कि","अनिद्रा को कैसे ठीक किया जाए। बिल्कुल सरल।"]],[3312,["सहज योगी: एक लड़के ने लिखा है कि आत्मा","के साक्षात्कार के लिए जो भी फार्मूला या जो","भी हम कर सकते हैं,"]],[3319,["प्लीज बताइए, ताकि वह एनर्जी मेरी बॉडी के साथ","सिंक्रोनाइज (समकालीन बन) या रेजोनेंस कर सके।"]],[3325,["मैंने पहली बार यह डिस्कोर्स (प्रवचन) अटेंड किया है।","श्री माताजी: ऐं?"]],[3329,["सहज योगी: मैंने पहली बार ये डिस्कोर्स","अटेंड किया है।","श्री माताजी: हाँ"]],[3331,["श्री माताजी : ये किस साहब का है प्रश्न?","आपका है बेटे? बहुत ख़ुशी की बात है।"]],[3337,["इन्होंने बहुत सही बात पूछी कि मुझे आत्मा","साक्षात्कार चाहिए। बस हो गया।"]],[3342,["बस इतना बहुत है - वो हो जाएगा। लेकिन जब","ये एनर्जी आपके अंदर से बहने लग जाये"]],[3347,["तब इसके बारे में सीखना पड़ेगा, जानना पड़ेगा,","क्योंकि योग तो घटित हो गया लेकिन योग का","दूसरा अर्थ होता है युक्ति - कौशलम।"]],[3357,["माने योग जानने के बाद, आपको समझना चाहिए,","कि इसकी कुशलता क्या है, किस तरह से इसको","वर्क आउट करना चाहिए।"]],[3363,["योग का एक ही अर्थ नहीं होता है। योग का एक","तो अर्थ हो गया कि यूनियन हो गया"]],[3367,["और उसके बाद में उसकी कुशलता आनी चाहिए,","उसकी डेफ्टनेस आनी चाहिए।"]],[3374,["हो गए? नहीं?","साधक: आपने हमें बताया आत्मा"]],[3382,["आपने हमें बताया है कि आत्मा ही परमात्मा है,","आत्मा ईश्वर का प्रतिबिंब है। फिर ऐसा क्यों होता है,"]],[3389,["जब कोई मर जाता है, हम प्रार्थना करते हैं,","\"ईश्वर दिवंगत आत्मा को शांति प्रदान करें।\""]],[3395,["जैसे कि ईश्वर और आत्मा दो अलग-अलग चीजें हैं।","श्री माताजी: नहीं"]],[3399,["साधक: यह सच है कि ईश्वर सर्वोच्च है","हमें प्रार्थना करनी होगी..."]],[3401,["श्री माताजी : ठीक है, मैं आपके प्रश्न का उत्तर दूँगी।","इसका उत्तर देना मुश्किल नहीं है, क्योंकि","जब आप मरते हैं,"]],[3406,["उस समय आपके साथ जो होता है वह एक अंश है।","आप सिर्फ आत्मा नहीं बनते, आप जीव-आत्मा बन","जाते हो, आप एक जीव आत्मा बन जाते हो।"]],[3413,["इसलिए आत्मा के साथ जीव अभी भी उसके साथ है","और इसलिए अंधेरा है, क्योंकि जीव अभी","भी आत्मा के आसपास है,"]],[3422,["क्योंकि अगर जीव आत्मा को घेर रहा है, तो हम कहते","हैं कि, \"हे भगवान, कृपया इस आत्मा को या","इस जीवात्मा को,"]],[3427,["उसकी आत्मा को शांति दें,\" उसकी आत्मा को नहीं,","उसकी जीव-आत्मा को, जीवात्मा को, ताकि वह एक","व्यक्ति बेहतर बन सके।"]],[3437,["और जब उसका पुनर्जन्म होता है, तो वह लालायित","नहीं होता है। मृत्यु के बाद भी यदि उसका जीवात्मा","सुखी या शांत नहीं है,"]],[3446,["तो वह उसके चारों ओर लालायित हो सकता है, वह","इधर-उधर मंडरा सकता है और समस्याएं पैदा","कर सकता है, इसीलिए हम कहते हैं।"]],[3453,["आत्मा अपने आप में, शांति ही है। लेकिन यह","जीवात्मा है, यह आत्मा नहीं है।"]],[3460,["आत्मा से अभी भी तीन तत्व जुड़े हुए हैं। केवल पृथ्वी","तत्व और जल तत्व छूट जाते हैं। शेष अभी भी हैं।"]],[3475,["साधक : क्या इस रियालाईज़ेशन के लिए जो आपने","बताया है, उसके लिए क्या आदमी गृहस्थ आश्रम में","रह कर यह सब चीज़ प्राप्त ..."]],[3483,["श्री माताजी : अरे भाई अगर गृहस्थ आश्रम में","नहीं होगा, तो होगा ही नहीं रियालाईज़ेशन।"]],[3487,["उल्टा हाल है सहज योग में। सहज योग में अगर","आप गृहस्थ आश्रम में नहीं रहेंगे, तो सहज योग","नहीं लाभ होता।"]],[3493,["अगर कोई सन्यासी बाबा होते तो हम उनसे कहते","भैया कपडे बदल के आ जाओ।"]],[3500,["गृहस्थ आश्रम तो बिलकुल त्यागना नहीं - ये","सब आइडियाज पता नहीं कहाँ से आ गईं।"]],[3506,["भगेड़ूपना होता है यह।"]],[3509,["साधक: इतना कॉन्सेंट्रेशन, इतना रियालाईज़ेशन,","ये आदमी को एकांत तो चाहिए इसके लिए।"]],[3513,["श्री माताजी: कोई ज़रूरी नहीं। अपने अंदर ही","सब कुछ है बेटे। एकांत की कोई ज़रुरत नहीं।"]],[3518,["अंदर ही घटित होता है, अंदर ही आप पाते हैं, और","उसमें आप जान लेते हैं, कि जहाँ आप बैठे हुए हैं,"]],[3525,["जिस वातावरण में, उसी में वो शक्ति आ गई।","लेकिन अगर आप हिमालय पर चले जाएँ,"]],[3531,["वहाँ पर भी जाकर के आप वरीड (चिंतित) रहेंगे,","और वहाँ भी आप चाहेंगे कि अपनी झोपडी के","आसपास कोई चीज़ और बना लें,"]],[3537,["और किसी तरह से अपने को सुरक्षित रखें, पर यहाँ","तो जब आत्मा में आप जागृत हो गए, तो सबके","अंदर रहते हुए, अंदर से आप शांत रहते हैं।"]],[3549,["साधक : आत्मिक विकास के लिए एक आदमी, जो","शराब पीता है, सिगरेट पीता है, मीट खाता है,"]],[3555,["और जैसे मुस्लिम धर्म में चार बीबियाँ हैं,","हिन्दू धर्म में एक ही है, तो ये, वैसे तो इंसान","सारी दुनिया में एक है,"]],[3562,["तो ये बहुत सारे विद्यवानों का, स्पिरिचुअल,","आत्मिक विकास की शक्तियों को बढ़ाने के लिए","(अस्पष्ट) अलग-अलग ख़्यालात रहे,"]],[3572,["श्री माताजी: नहीं, अलग-अलग कोई ख़्यालात","नहीं, भाईसाहब"]],[3574,["साधक : नहीं, इसमें क्या फर्क है? कहते हैं भई,","कि जो सिगरेट पीता है ठीक नहीं है, मीट खाता है","ठीक नहीं है,"]],[3580,["पाँच बीबियाँ रखता है ठीक नहीं है - आत्मिक विकास","उसका जल्दी नहीं हो सकता - वो अपने आपको"]],[3586,["श्री माताजी: समझ गए मैं, आप बैठ जाईए। मैं"]],[3589,["साधक: खाने, पीने में, पहनने में,","(अस्पष्ट) इसके बारे में क्या..."]],[3591,["श्री माताजी : बैठिए आप। देखिये, जो चीज़ें आत्मा के","विरोध में पड़तीं हैं, वो चीज़ें नहीं खानी चाहिए।"]],[3598,["जो चीज़ आत्मा के विरोध में पड़ती है, या चेतना","के विरोध में पड़ती है, वो नहीं करनी चाहिए।"]],[3603,["अब जब मोहम्मद साहब आए थे तो उन्होंने बताया,","\"भई, शराब मत पियो,\" क्योंकि तब तक","सिगरेट नहीं आई थी।"]],[3610,["इसलिए वो नानक साहब बनके आए, उन्होंने","कहा, \"भैया, अब सिगरेट मत पियो।\""]],[3614,["तो अब कुछ लोग आ के मुझे कहते, इन दोनों ने","ये तो नहीं कहा था कि, \"गांजा मत पियो।\""]],[3620,["तो मैंने इनसे ये कहा कि भई, सबकी तुम लिस्ट","बना के दे दो जो जो पी सकते हैं"]],[3625,["- मुझे तो मालूम भी नहीं क्या-क्या पीते","हैं और क्या क्या करते हैं।"]],[3629,["मतलब, ये तो ऐसी चीज़ है न कि,","'आ बैल मुझको मार,' ये पॉलिसी।"]],[3633,["अच्छे भले बैठे हुए हैं, एकदम से आपने शुरुआत","कर दी पीने को, तो उनसे क्या कहा जाए।"]],[3638,["लेकिन अब ये है कि समझ लो, कि हो सकता है कि","मैंने एक दो बात अभी नहीं कहीं और हम चल बसे"]],[3644,["तो लोग कहेंगे कि, माताजी ने इसको तो","मना नहीं किया था, तो यही करो।"]],[3648,["अरे भई सीधा हिसाब ये लगाइए कि जो चीज़","अपनी चेतना के विरोध में जाती है, माने ये"]],[3657,["कि जो आप शराब पिएँ, वो आपकी चेतना के विरोध","में जाती है कि नहीं जाती - सीधा हिसाब।"]],[3663,["है न, तो वो न करें। अच्छा सिगरेट पिएँ, उससे कैंसर","होता न, वो आपके शरीर के विरोध में जाता है।"]],[3670,["अच्छा रही बात गोश्त खाने की, इसके बारे में","किसी ने भी नहीं कहा, 'गोश्त मत खाओ'"]],[3674,["ऐसा किसी ने नहीं कहा, 'गोश्त मत खाओ।'","ये तो बनाई हुई चीज़ें हैं।"]],[3678,["ऐसा नहीं कहा, लेकिन ये ज़रूर कहा है कि,","अब जो भी है, संतुलित खाना खाइए।"]],[3683,["वेजीटेरियन हैं, वेजीटेरियन रहो। गोश्त खाने","पर जब लोग आते हैं, तो मछली, मुर्गी, घोडा,","गाडी, सब खा जाते हैं।"]],[3695,["और जब वेजीटेरियन पे आते हैं, तो ये हद्द हो जाती है","कि, खटमलों को बचाएँगे, मोस्किटोएस (मच्छर) को","बचाएँगे - भई कोई चीज़ का तुक होना चाहिए।"]],[3706,["हरएक चीज़ का तुक होता है। इसका कोई मतलब,","जैसे आप समझते हैं कुछ लोग ऐसे होते हैं"]],[3712,["कि मॉस्किटो को - अब मॉस्किटो को क्या मैं","आत्मसाक्षात्कार दे सकती हूँ? एक सीधा हिसाब","- दे सकतीं हूँ क्या?"]],[3718,["खटमलों को दे सकती हूँ, मुर्गियों को दे","सकती हूँ - नहीं दे सकती हूँ।"]],[3723,["लेकिन शारीरिक दृष्टि से जिस आदमी को","जिस चीज़ की ज़रुरत है वो वह खाये।"]],[3729,["लेकिन अगर लोग सिर्फ गन्दी ही चीज़ें खाना","चाहें, उसे क्या कह सकते हैं।"]],[3734,["जिसको जो सूट करता है वो खाना चाहिए। अब इसका","मतलब है - नानक साहब थे, वो तो गोश्त खाते थे।"]],[3742,["कबीरदास खाते थे गोश्त, अपने मोहम्मद साहब","खाते थे। राम खाते थे, बुद्ध भी खाते थे"]],[3751,["और महावीर भी खाते थे। लेकिन उनका ये नहीं था","कि अब खाने पे आये, तो खाने पे ही लग गए।"]],[3758,["क्योंकि खाने पीने से आत्मा पे असर तब आता","है, जब आपके अंदर ऐसी प्रवृत्तियाँ आ जाएँ,"]],[3765,["जिससे आप हिंसक हो जाएँ। और उससे भी असर","आता है कि अगर आप एकदम बंदगोभी हो के","पड़े रहें - कैबजिस।"]],[3775,["कुछ लोग जो होते हैं, वो बिलकुल उस प्रकार हो जाते","हैं, कि जैसेकि कुछ उनके अंदर बिलकुल कोई","शक्ति ही नहीं।"]],[3781,["अब आप देखिएगा, कि बीमारियाँ भी इस तरह","से आती हैं, अतिशयता से।"]],[3785,["जो लोग बहुत ज़्यादा गोश्त खाते हैं, वो","आततायी होते हैं, अहंकारी होते हैं।"]],[3791,["और उनके अंदर बीमारियाँ क्या आ जातीं हैं?","ऐसे लोगों का ब्लड प्रेशर ज़्यादा हो सकता हैं,"]],[3795,["हार्ट अटैक हो सकता है उनको क्योंकि ओवरएक्टिविटी","हो गई। और जो लोग सिर्फ घास खा के रहते हैं","समझ लीजिए,"]],[3803,["उनको सब लेथार्जी आ जाती है, उनको लेथार्जिक","हार्ट होता है।"]],[3807,["आज ही एक साहब आये थे - अग्रवाल थे, बेचारे।","तो कहने लगे कि उनके लेथार्जिक हार्ट, लेथार्जिक","लिवर, लेथार्जिक इंटेसटाइन्स।"]],[3815,["तो मैंने कहा देखिए, आप तो गोश्त नहीं खा","सकते क्योंकि आपने कभी खाया नहीं"]],[3820,["लेकिन आप ऐसा करिए कि प्रोटीन खाएं ज़्यादा।","तो, \"माँ प्रोटीन कहाँ?\" मैंने कहा मिलता है न,","खोजो तुम खा नहीं न सकते हो अब और।"]],[3828,["बहुत खा चुके तुम ये। कार्बोहाइड्रेट्स नहीं","खाना चाहिए तुम्हें। ये समझाने की बात है।"]],[3833,["अब किसी ने कहा है कि गीता में लिखा है। बेहराल,","मैं तो इतना ही कहूँगी, कि गीता में सबसे पहले कृष्ण","ने ये कहा कि, \"अर्जुन, तू इन सबको मार।\""]],[3844,["अहिंसा की तो उन्होंने बात ही नहीं करी, मतलब","उनको अहिंसा में कैसे ला के डाल दिया पता नहीं।"]],[3849,["उन्होंने तो इंसान को मारने का कहा, जानवर का","तो छोड़ो और उसपर गुरु तक को मारने को कहा"]],[3855,["तो वो कैसे कहेंगे कि, \"तुम इसको नहीं मार, उसको","नहीं मार।\" वो तो पहले ही कहते कि, सब मरा हुआ है।"]],[3861,["ऐसी उलटी बातें भी सब जगह हुईं हैं। बाइबिल","में भी बहुत गलत कर दिया है।"]],[3867,["कुरान में भी ऐसी चीज़ें कर दीं हैं - ये तो सबका धंधा","है - क्योंकि ऐसा नहीं करेंगे तो इनकी चलेगी कैसे।"]],[3874,["कुछ न कुछ ऐसा बना देते हैं, कि जिससे कोई न","कोई चीज़, एक ग्रुप बन जाए।"]],[3883,["ये सब जो है, गठबंधन बनाये हुए हैं। समझने की बात","है कि चेतना के विरोध में, सब शराब वगैरह ये जाता है"]],[3890,["इसलिए शराब के विरोध सबने कहा है चाहे मोसेस को","ले लीजिए आप। अब ईसा मसीह ने नहीं कहा","आप कहेंगे"]],[3896,["लेकिन ऐसी बात नहीं। ईसा मसीह इस जगह पैदा","हुए हैं और ये जगह जो है वहाँ पर दूसरी बात","करने की थी।"]],[3902,["जहाँ जो बात करने की, वही तो बात होएगी।","अब मैं कुण्डलिनी के जागरण के लिए अगर आई हूँ,","तो मैं उसी की बात करुँगी आपसे।"]],[3909,["लेकिन इस वक्त ऐसी है कि सभी बात करनी पड़ेगी","नहीं तो मुझे डर लगता है कि आप जो नहीं बात","करुँगी, उसी को पकड़ बैठिएगा।"]],[3917,["इसलिए बेहतर है कि मैं सभी बातें कह जाऊँ,","लेकिन तो भी पकड़ने वाले पकड़ेंगे।"]],[3923,["जिनको यही काम है सुबह से शाम किसी की","पकड़ - लूप होल्स जिसे कहते हैं न -"]],[3928,["जैसे अब कोई अगर आप चोर के पास जा के पूछिए","किसी बैंक के बारे में, तो वो ये बता देगा कि इसमें","कैसे आप घुस सकते हैं - बराबर।"]],[3939,["लेकिन उसके मैनेजर से पूछिए तो कहेगा,","देखिए इसमें ये मज़बूती है, वो मज़बूती है।"]],[3945,["लेकिन चोर ही बता सकता है कि इसमें आप कैसे","घुस सकते हैं, कितने भी आप मजबूत बना जाइए,","तो भी हम घुस के दिखाएंगे।"]],[3952,["ये इंसान की खूबी है। हर धर्म प्रचारकों ने अपनी तरफ","से पूरी कोशिश की कि भई इंसान को अकल में लाएं।"]],[3960,["अब महावीरजी को इस हद्द तक पहुँचा दिया कि","अब खटमल, खटमल एक उसको लाया,"]],[3966,["एक ब्राह्मण को लाया, उसको कहें तुमपे खटमल","लगाते हैं और तुमको इतना पैसा देते हैं।"]],[3972,["उसके बाद वो खटमल उसको जब चूस लेते हैं और","ब्राह्मण को छुट्टी हो जाती है, तो बड़ा धर्म कार्य हो गया"]],[3978,["हमने इतने खटमलों को खून खिला दिया","एक ब्राह्मण का। अब ये कोई तरीका हुआ?"]],[3988,["मनुष्य को सूझ-बूझ बहुत है लेकिन धर्म के मामले","में बहुत कम। और खाने-पीने का ज़्यादा विचार","करना भी ठीक नहीं।"]],[4004,["रात दिन जो आदमी खाने-पीने का ही विचार करते","रहेगा वो आत्मा को क्या पाएगा आप ही बताइये।"]],[4010,["अब उपास होने का है, तो उपास ही के बारे में","लोग सोचते रहेंगे कि क्या खाएँगे कल उपास है।"]],[4014,["और मार हाय-हाय तौबा मच जाएगी - हनुमान जी का","अवतार हो जाएगा उस वक़्त, कि इनका उपास है।"]],[4020,["पता हुआ दूर से ही पता हो जाता है कि यहाँ कोई उपास","कर रहा है। भगवान बचाए रखे ऐसे उपासवी लोगों से।"]],[4025,["सहज योग में दूसरा नियम है कि कोई उपास","नहीं करेगा भगवान के नाम पर।"]],[4030,["अपने लिए करना है तो करो। लेकिन जो आदमी","उपास करेगा उसको गाँव से बहार जाना चाहिए।"]],[4035,["क्योंकि किसी को उनकी बातें नहीं सुनने की।","यहाँ तो सबमें शहीदीपना है ना,"]],[4039,["\"मैंने इतना उपास किया, तो मैं","सबको डंडे मार सकता हूँ।\""]],[4043,["\"मैंने देश के लिए इतना त्याग किया,","तो मैं सबकी जान खा सकता हूँ,\""]],[4046,["भई काहे को किया, किसने बताया? वो भी एक","मर्त्य्रडम (शहादत) है, दिमागी जमा खर्च।","किया तो किया, मज़े में रहो।"]],[4064,["तो खाने-पीने का विचार, अति रखना भी, दोषमय","है। पर पार हो जाइए फिर बात करेंगे,"]],[4071,["क्योंकि अभी करने में आप बुद्धि के तर्क पर","चलेंगे। इसलिए पहले पार हो जाइए।"]],[4075,["किसी के लिए कोई चीज़ का कमपलशन नहीं है","खाने-पीने का, लेकिन अपने से जो बड़े जानवर हैं,","उनको मत खाइए"]],[4081,["और सहज योग में ये नहीं कि आप सब को गोश्त","ही खाना है या ये ही खाना है - जो खा रहे वो ही ठीक है,"]],[4087,["ज़्यादा मत खाइए। कम खाइए और कम भी","इतना नहीं खाइए कि भूखे मरिए।"]],[4091,["दोनों के बीच में रहना है, मध्य मार्ग है।","कोई चीज़ का एक्सट्रीम व्यू मत लीजिए।"]],[4099,["जो आपको बीमारी होगी, उसके अनुसार","आप अपना डाइट रखिए।"]],[4103,["हम तो सिर्फ इसपे कहेंगे, कि किसे प्रोटीन","खाना है, किसे कार्बोहाइड्रेट्स खाना है,","और किसको फैट्स खाना है।"]],[4111,["समझे न आप। और इस पर आप अपना तय कर","लीजिए आप जिस तरह से भी खाना खाना चाहें।"]],[4115,["उसके प्रति बहुत ज़्यादा विचार करना है, तो अपने","हिन्दुस्तानियों का ध्यान ही, चित्त ही खाने पे है।"]],[4120,["ये भी बात है। हिंदुस्तानी लोग बहुत ज़्यादा खाने की","सोचते हैं। रात-दिन उनका विचार पता नहीं क्यों"]],[4125,["इतना खाने पर और इतने नख़रे खाने में करते हैं,","कि मैंने कोई देश में इतने नख़रे करने वाले लोग","नहीं देखे जितने हिंदुस्तान में हैं।"]],[4132,["और हालाँकि हम लोग गरीब लोग हैं, कहने के लिए,","लेकिन जितने नख़रे हिन्दुस्तानियों के हैं, आपको कहीं","नहीं मिलेंगे ऐसे, जितने नख़रे हम करते हैं।"]],[4141,["औरत जो है, वो भी होशियार है। वो भी अलग-अलग","खाना बना-बना के आदमी की ज़बान ख़राब","कर देती है।"]],[4148,["क्योंकि अच्छा तरीका आदमी को घर बुलाने","का। उसकी ज़बान पहले ख़राब कर दो।"]],[4153,["जब उसको काबू में कर लिया, तब फिर वो","दौड़ता-फिरता है, उस जीभ के पीछे में।"]],[4159,["और इस कदर नख़रे खाने के मामले में हैं","कि मैं आपसे बता नहीं सकती।"]],[4163,["बंगाल में अब जैसे है, रोहू फिश खाएँगे।","वहाँ रोहू होता नहीं, तो रुहु खाएँगे - वही खाएँगे","जो होता नहीं।"]],[4170,["और वो जाता है सेंट्रल इंडिया से। एक बार वहाँ","रोहू फिश नहीं मिली - मतलब उनके यहाँ","छोटे-छोटे पोखर में मिल जाती है,"]],[4177,["तो भूखे मरने लग गए, तो हमारे बम्बई से कुछ","लोगों ने बड़ा पैसा-वैसा इकट्ठा कर के एक","पूरा जहाज़ के जहाज़ भेजा।"]],[4185,["उन्होंने वापस कर दिया कि हम तो सी फिश खाते","नहीं। लाट साहिबी देखिए!"]],[4191,["और सब के सब शिप वो वापस आ गए","- 'सी फिश हम नहीं खा सकते।'"]],[4195,["दुनिया में कोई ऐसा नहीं आप कहीं जा के देखिए,","कि जो सी फिश नहीं खाता - ये फिश खाता है।"]],[4201,["खाने को बैठो, तो वो चाहिए, ये चाहिए, इसमें","नमक ठीक नहीं उसमें - ये सब कहीं नहीं होता।"]],[4206,["ये अपने ही देश में है और इतना ज़्यादा खाने के","हम लोग शौक़ीन हैं, इसकी कोई हद्द नहीं।"]],[4212,["इसलिए खाने की तो बात आप ज़रा भूल","ही जाइए थोड़ी देर के लिए।"]],[4216,["अभी थोड़ी देर बाद खाने का टाइम","आएगा - अभी टाइम नहीं है।"]],[4222,["सहज योगी: बोध की भावना से परे सत्य है या","वह सत्य है, जो हम देखते हैं और जो कुछ भी","हम अनुभव नहीं करते हैं?"]],[4229,["श्री माताजी: हां, यह सही है। यह एक बहुत अच्छा","प्रश्न है - क्या सत्य इंद्रिय बोध से परे है?"]],[4236,["पूर्णतया है ही। क्योंकि अगर हम अपनी इंद्रियों","के माध्यम से जो अनुभव करते हैं, जो कुछ भी हम","अपनी इंद्रियों के माध्यम से देखते हैं,"]],[4247,["वह सत्य है, तो हमें अब और खोजने की आवश्यकता","नहीं है। हम अपनी इंद्रियों के माध्यम से जो कुछ भी","देखते हैं, वह बहुत स्पष्ट है, स्थूल है - सूक्ष्म नहीं।"]],[4265,["स्थूल के पीछे क्या है, वह हम अनुभव नहीं","कर सकते, समझ नहीं सकते।"]],[4269,["उदाहरण के लिए, हम यह नहीं कह सकते","कि परमाणु कैसे बनाया जाए।"]],[4278,["हम यह नहीं कह सकते कि कैसे एक अमीबा","को एक इंसान बनाया जाता है।"]],[4283,["हम अपनी इंद्रियों की धारणा के माध्यम से, एक बंदर","को इंसान नहीं बना सकते हैं। क्या हम कर सकते हैं?"]],[4290,["हम उस सूक्ष्म चीज को नहीं कर सकते, जो स्थूल","के पीछे है। इसलिए हम इंद्रियों के माध्यम से","अनुभव नहीं कर सकते हैं,"]],[4304,["लेकिन एक बार जब हम इसे अनुभव कर लेते हैं,","तो आप इसे अपनी इंद्रियों के माध्यम से","महसूस कर सकते हैं।"]],[4309,["यह दूसरी स्थिति है। हो गया अब? मुझे लगता है,","कि पहले ध्यान करना बेहतर है।"]],[4317,["क्या प्रश्न है ?"]],[4319,["साधक: कोई क्या करे या क्या अभ्यास करे,","नंबर 1, अपने मन के विचारों की शुद्धि के लिए,"]],[4327,["नंबर 2, अपने भीतर की मनोग्रंथि को दूर","करने के लिए?"]],[4331,["श्री माताजी : ठीक है।","साधक: और नंबर 3, अपने आप में आत्मविश्वास","पैदा करने के लिए।"]],[4336,["श्री माताजी: यह बहुत अच्छा प्रश्न है। बैठ जाइए।","आपको बस अपनी आत्मा को प्राप्त करना है।","आपको अपनी आत्मा बनना है।"]],[4344,["जब यह एक बार आपके साथ घटित होता है,","वास्तव में पहली चीज जो होती है जब कुंडलिनी","आपके भीतर जागृत होती है,"]],[4351,["एक बार जब वह इस आज्ञा चक्र को पार कर जाती है,","तो आपको निर्विचार समाधि प्राप्त होती है,","आप विचारों से परे चले जाते हैं।"]],[4356,["यह पहली बात होती है। फिर, अपना विश्वास कैसे","प्राप्त करें? आत्मा आपका विश्वास है, क्योंकि अभी","तक आपने अपने गुणों को नहीं जाना है,"]],[4369,["आपने अपनी सम्पदा को नहीं जाना है, आपने अपनी","सुंदरता को नहीं जाना है, अपनी महिमा को","नहीं जाना है।"]],[4374,["आत्मा की आंखों से ही, जब आप जानेंगे कि आप","कितने अद्भुत हैं, तो आप इसे जान सकेंगे।"]],[4380,["उदाहरण के लिए, जब तक यह यंत्र मुख्य से जुड़ा नहीं","है, तब तक इसका कोई अर्थ नहीं है। यह शून्य है,","इसका कोई मूल्य नहीं है।"]],[4387,["लेकिन एक बार जब यह जुड़ जाता है, तो इसका","मूल्य होता है। उसी तरह, एक बार जब आप मुख्य से","जुड़ जाते हैं, आपका अपना मूल्य है।"]],[4392,["जब आप अपना मूल्य जानते हैं, तो आपकी पूरी मूल्य","प्रणाली बदल जाती है और आप स्वयं इसका","मूल्यांकन एक अलग तरीके से करते हैं,"]],[4400,["कि आप जानते हैं कि आप आत्मा हैं। इस तरह से","आप अपना आत्मविश्वास प्राप्त करते हैं।"]],[4405,["अब इसका शुद्धिकरण भाग, वह भी बिना प्रकाश","के, आप स्वयं को शुद्ध नहीं कर सकते।"]],[4410,["आप अंधेरे में जो भी शुद्धि करते हैं, एक तरफ आप","सफाई कर रहे होंगे, दूसरी तरफ आप गंदे हो सकते हैं।"]],[4417,["जीवन में ऐसा बहुत होता है। देखिए, कुछ लोग कहते","हैं, \"मैं अपने अहंकार पर विजय प्राप्त करने","जा रहा हूं,\""]],[4422,["आप इस पर विजय प्राप्त नहीं कर सकते। आप","देखिए, आप उसके साथ संघर्ष करते चले जाते हो।"]],[4424,["यह आपसे लड़ता है और यदि आप अपने अहंकार को","कम करने की कोशिश करते हैं, तो आपको अपना","सुपर अहंकार मिलता है"]],[4429,["मतलब, आपको एक नम्र व्यक्ति मिलता है,","आप बन्दगोभी की तरह बन जाते हो।"]],[4432,["या तो आप यह या वह बन जाते हो","- आप मध्य में नहीं हो सकते।"]],[4435,["अब कुंडलिनी से क्या होता है। जब वह उठती है,","तो यहाँ ऊपर आती है - इस बिंदु पर जब वह","जागृत होती है, यह केंद्र"]],[4443,["यह शोषित करता है, यह आपके अहंकार और आपके","प्रति अहंकार को दोनों तरफ से अवशोषित करता है।"]],[4449,["दोनों चीजें - आपके संस्कार, आपके पाप और","सब कुछ और दूसरी तरफ आपका अहंकार।"]],[4453,["दोनों अंदर खींचे जाते हैं। एक बार दोनों को खींच लिया","जाता है, तो आप देखते हैं, तुरंत क्या होता है,"]],[4458,["कि आपका सहस्त्रार खुल जाता है - यह हिस्सा,","फॉन्टानेल हड्डी क्षेत्र और ब्रह्मरंध्र खुलता है और आप","उस सूक्ष्म जागरूकता में प्रवेश करते हैं।"]],[4466,["तो, सभी तथाकथित कर्म आदि अवशोषित कर लिए","जाते हैं। आखिरकार कर्म कौन करता है - अहंकार है।"]],[4472,["एक बार यह शोषित होने पर कोई अहंकार नहीं बचता।","उस निरहंकार अवस्था में आप ईश्वर के साथ एक हो","जाते हैं। तो, यह एक सहज, स्वचालित घटना है।"]],[4484,["कुण्डलिनी जागरण के फलस्वरूप,","ये सारी चीज़ें तुरंत हो जाती हैं।"]],[4496,["सहज योगी: शरीर में प्रवेश करने से पहले जीवात्मा","क्या था?","श्री माताजी: ऐं?"]],[4499,["सहज योग: शरीर में प्रवेश करने से पहले जीवात्मा","क्या था और मरने के बाद उसका क्या होता है?"]],[4505,["श्री माताजी: अभी ये चले पूछने - ये पूछ रहे है कि,","जन्म से पहले जीवात्मा क्या है और बाद में क्या?"]],[4511,["बेटे अभी आप एक मनुष्य हो, ठीक है? अभी आपको","इन चीजों के बारे में चिंता नहीं करनी चाहिए।"]],[4519,["सब कुछ आप एक व्याख्यान में नहीं जान","सकते, क्या आप जान सकते हैं?"]],[4523,["तो अब, इन बातों के बारे में चिंता मत करो।","अतीत या भविष्य के बारे में चिंता क्यों करें?"]],[4529,["क्योंकि अतीत समाप्त हो गया है (क्या? पी रहे चाय)","अतीत समाप्त हो गया है और भविष्य का","अस्तित्व नहीं है।"]],[4539,["इसलिए हमें वर्तमान में रहना होगा। अब, वर्तमान में","कैसे रहें? अभी, अगर मैं कहूं, अपने आप पर ध्यान दें","- क्या आप चित्त रख सकते हैं?"]],[4545,["इसलिए, कुण्डलिनी को जागृत होने दो, आप अपना","बोध प्राप्त कर लो, फिर हम भूत और भविष्य की","बात करेंगे। अभी आप वर्तमान प्राप्त करें।"]],[4558,["सहज योगी: आखिरी सवाल माँ। आपके अनुसार,","सहज योग द्वारा आत्मा परमात्मा का","मिलन होता है।"]],[4563,["अगर ऐसा होता है, तो हमारे ऋषि मुनि आदि,","वहाँ हिमालय पर्वत आदि एकांत स्थल पर"]],[4570,["कुण्डलिनी जागृत करने के लिए, परमात्मा","की प्राप्ति के लिए, क्यों जाते थे?"]],[4576,["श्री माताजी: इन्होंने सवाल ये पूछा है कि","हमारे - इन्होंने एक प्रश्न पूछा है,"]],[4580,["कि यदि इस संसार में आत्मा का साक्षात्कार किया","जा सकता है, तो ऋषि मुनि हिमालय क्यों जाते थे?"]],[4589,["नानक ने इसका उत्तर दिया है,"]],[4591,["'काहे हे रे बन खोजन जाई","सदा निवासी सदा अलेपा तोहे संग समाये,","पुष्प मध्य जो बास बसत है मुकुर माहि जस झाई,","तैसे ही हरि बसै निरंतर घट हो खोजो भाई'"]],[4607,["और अंत में कहते हैं ,","'कहे नानक बिन आपा चीन्हे मिटे न भ्रम की काई'"]],[4613,["ये तो पागलपन है, आप हिमालय पर जाओ नहीं तो","कहीं भी जाओ - ये तो पागलों को क्या कहें","- कोई ज़रुरत नहीं जाने की।"]],[4619,["दूसरी बात ये, कि उनकी शायद माँ नहीं रही होगी","उनको बताने को कि, \"भैया कहाँ जा रहे हो?\""]],[4626,["हो सकता है। यही बात एक कह सकती हूँ मैं तो","और क्या कहूँ, कि ये भी अच्छा है कि","हिमालय चले जा रहे हैं।"]],[4635,["सब प्रकार कर देखे लोगों ने - हो गया अब पा लो बस।","सब हो गया, हिमालय गए - आप लोग बहुत हो आए","हिमालय में, पिछले जनम में।"]],[4645,["अब इस जनम में यहीं ले लीजिए। गिरी कंदरों में अगर","परमात्मा मिलते होते, तो फिर क्या कहना था।"]],[4656,["भई, संसार में रहना सबसे बड़ा यज्ञ है। पलायन","करना तो बहुत ही आसान चीज़।"]],[4663,["संसार में रह के, गृह कर्म कर के, और परमात्मा को","पाना, ये सबसे अच्छी विधि है। यही सहज योग है।"]],[4674,["ये जो द्राविड़ी प्राणायाम हैं, ये करने की ज़रुरत नहीं","और दूसरी बात ये कि आपकी अगर माँ है कोई,"]],[4682,["तो वो तो नहीं चाहेगी, कि अपना बेटा","हिमालय जाए, में जाके ठण्ड में बैठे।"]],[4686,["अभी यहाँ भी ये लोग ज़रा ठण्ड में बैठे, तो मेरा जी","कुम्भला गया, कि बच्चे बाहर बैठे, ठण्ड में बैठे।"]],[4692,["तो हिमालय में तो मैं किसी को नहीं जाने","दूँगी। आप चाहें तो भी।"]],[4702,["होंगे ऋषि मुनि जाते होंगे, तो उसको हम क्या करें?","हम तुमको नहीं जाने देंगे, बस सीधी बात है।"]],[4714,["कौन से ऋषि गए थे हिमालय ये तो मुझे नहीं पता","- कोई गए थे क्या? ऑथेंटिकली (प्रमाण के अनुसार)","कौन से ऋषि गए थे?"]],[4721,["सहज योगी: गर्मी में तो .....","श्री माताजी: ऐं?"]],[4724,["सहज योगी: गर्मी में हिमालय .....","श्री माताजी: हाँ, गर्मी में जाओ हिमालय,","बड़ा अच्छा रहेगा, वो दूसरी बात है।"]],[4729,["लेकिन राजा जनक का किस्सा है, श्री रामचंद्रजी","के वक़्त, कि उनको विदेही कहा जाता था","और वो तो राजा थे।"]],[4749,["सहज योगी: क्या आप सत्य को जानते हैं?","अगर हाँ, तो कैसे?","श्री माताजी: ऐं?"]],[4752,["सहज योगी: क्या कोई सत्य को जानता है? अगर हाँ,","तो कैसे? इंद्रियों के माध्यम से, या सुपर इंद्रियों के","द्वारा, या बिना इंद्रियों के?"]],[4760,["श्री माताजी: एक साहब ने सोचा है कि, सत्य हम","कैसे जान सकते हैं - इंद्रियों के माध्यम से,","सुप्रा इंद्रियों के माध्यम से"]],[4765,["सहज योगी: या इंद्रियों के बिना","श्री माताजी: आत्मा के माध्यम से, आत्मा के माध्यम","से, अपनी आत्मा के माध्यम से आप जानेंगे।"]],[4778,["न तो इंद्रियों से और न ही किसी चीज से,","अपनी आत्मा के द्वारा"]],[4783,["क्योंकि जब आत्मा जुड़ी होती है या जब आत्मा","का प्रकाश आपके चित्त में आता है,"]],[4792,["आपका चित्त बन जाता है, फिर हो जाता है। मैं फिर","से कह रहीं हूँ - यह व्याख्यान नहीं है - सामूहिक रूप","से सचेत हो जाता है,"]],[4801,["ताकि आप स्पंदनात्मक जागरूकता के माध्यम","से, दूसरों को महसूस करने लगें,"]],[4804,["उस चैतन्य के माध्यम से, जो आप में से बह रहा है।","आप उन्हें अपनी उंगलियों पर महसूस करते हैं"]],[4813,["और आप देखते हैं कि चक्र आपकी उंगली पर हैं","- चाहे वे गर्म हों, ठंडे हों और हवा आ रही हो।"]],[4821,["तदनुसार यह पता लगाने के लिए, सहज योग में","डिकोड किया गया है और आप इसे सत्यापित करेंगे,","और आप पाएँगे कि वास्तव में ऐसा ही हो रहा होगा।"]],[4829,["दरअसल, मोहम्मद साहब ने साफ कह दिया है","कि 'कियामा के वक्त आपके हाथ बोलेंगे'"]],[4838,["हाथों की भाषा एक वैश्विक भाषा है, लेकिन","हाथों की अनुभूति, सार्वभौमिक है।"]],[4845,["लेकिन उस समय आपको जो अनुभूति होती है,","वह आपकी इंद्रियों के माध्यम से नहीं"]],[4849,["बल्कि आपकी उंगलियों, उँगलियों के पोरों पर","आपके केंद्रों के प्रबोधन के माध्यम से होती है।"]],[4856,["सात चक्र हैं - पांच, छह और सात।","यहाँ कुण्डलिनी का चित्र है, उसमें देखिएगा।"]],[4867,["ये सब सवाल आप बेटे धीरे-धीरे करो। आप","बहुत जल्दी भागे जा रहे हो।"]],[4871,["अभी फर्स्ट में घुसे हैं ना, तो अभी बी.ए. के","क्वेश्चन (सवाल) कैसे पूछ रहे?"]],[4882,["ठीक है? और किसी को कोई सवाल है तो पूछ","लीजिए, नहीं तो बीच में ही खड़े हो जाते हैं।"]],[4900,["साधक : माँ, मेरा कोई प्रश्न नहीं है, लेकिन","श्री माताजी: क्या बेटा?"]],[4903,["साधक : मुझे आपका आभार स्वीकार करना है। दो","हफ्ते पहले मैं एक सड़क दुर्घटना से बच गया।"]],[4913,["साधक : आप, आपने मुझे इस दुर्घटना से","बचाया। बस बचा लिया आपने।"]],[4919,["श्री माताजी: हिंदी में बोलिए फिरसे।","खड़े हो जाइए, खड़े होके बोलिए।"]],[4928,["साधक: दो सप्ताह पहले मैं सड़क पार कर रहा था।","दाईं तरफ से बहुत ज़ोर से गाडी आ रहा था।"]],[4943,["असल में, मैं तो बस आपकी तस्वीर हमेशा अपनी जेब","में रखता हूँ। बस, मुझे नहीं पता कि मैं कैसे बच गया।"]],[4955,["श्री माताजी: यही मैंने आपसे कहा था, कि भगवान","आपकी देखभाल करते हैं। भगवान के लिए चमत्कार","क्या है, चमत्कार क्या है भगवान के लिए!"]],[4965,["आपके किस्से से और भी एक किस्सा","सुना दें हम। आप बैठ जाइए।"]],[4969,["बहुत मेहरबानी, आपने कहा और बताया कि कैसे","वो सहज योग में आए सिर्फ दो हफ्ते और वो","कैसे उनकी बचत हो गई।"]],[4980,["लेकिन ऐसे बहुतों की बचत हुई है, बहुतों की","- बहुतों ने मुझे चिट्ठी लिख के भेजी। एक की"]],[4990,["उनकी बस गिर गई थी अस्सी फुट नीचे। और दो बार","गोल घूम कर वो चारों ज़मीन पर चारों पैर जम गए।"]],[5000,["और उसमें कोई मरा नहीं, कुछ नहीं हुआ और जो","ड्राइवर साहब थे मारे डर के भाग खड़े हुए।"]],[5008,["तो एक ने कहा, \"भई, मुझे तो बस चलना आता है।\"","उन्होंने कहा की अब क्या बस का बचाओ होगा।"]],[5011,["वो उतरे, उन्होंने चाबी चलाई, तो चाबी चल गई।","और गाडी ऊपर आ गई और सब लोग चले आये।"]],[5016,["तो उन्होंने कहा इसमें कोई न कोई संत बैठा हुआ है।","महाराष्ट्र की बात है - महाराष्ट्र में लोग मुझे जानते हैं।"]],[5023,["तो उसमें हमारी एक सहज योगिनी बैठी थी","- उसके हाथ में मेरी अंगूठी थी।"]],[5027,["\"हाँ, ये माताजी के संत।\" ये सब उसी के पैर पे","आने लग गए। \"तुमने बचा लिया।\""]],[5032,["ये तो कुछ भी नहीं, लेकिन आगे की बात बताएँ","आपसे, कि अभी-अभी ब्रैडफोर्ड में हम एक दिन","भाषण दे रहे थे।"]],[5040,["आठ बजे का वक़्त होगा - सात बजे से भाषण शुरू","हुआ। आठ बजे के समय एक लड़का कहीं 4 - 5 मील","दूरी पर और ऊपर से गिरा नीचे।"]],[5054,["उसके मोटरसाइकिल से गिरा और वो जा कर के","एक नाले की साइड में गिर पड़ा या कहिये कि","नदी की साइड में।"]],[5067,["तो सबने सोचा कि ये तो अब ख़तम हो गया लड़का।","तो उसी वक़्त एम्बुलेंस वैमबुलैंस आई, उसमें","15 - 20 मिनट लगे।"]],[5074,["जब लड़के को लाए तो देखा बिलकुल ठीक,","उसकी कोई हड्डी नहीं टूटी कुछ नहीं।"]],[5078,["उसने हमें कभी देखा नहीं था कुछ मतलब नहीं था।","और बिलकुल ठीक लेकिन एक जगह दर्द हो रहा था।"]],[5084,["तो उसको जब अस्पताल ले गए, तो उन्होंने कहा कि,","\"भई ये तो कुछ समझ में नहीं आया, न तुम्हारी","हड्डी टूटी, न कुछ हुआ"]],[5088,["तुम इतने बिलकुल जैसे कोई फुटबॉल उड़ाता है इस","तरीके से तुम नीचे गिरे और जैसे कि वैसे।"]],[5095,["तो उन्होंने कहा कि, \"जब मैं गिरा, तो बड़ी चोट आई","थी, लेकिन एक लेडी(महिला) आई सफ़ेद गाडी में"]],[5100,["और सफ़ेद साड़ी पहने थी, भारतीय महिला, और उसने","उतर के मुझे हाथ लगाया और मुझे ठीक किया","- उससे मैं ठीक हो गया ।\""]],[5109,["तो अखबार वाले बड़े - आप तो जानते हैं,","अखबार वालों को कोई चीज़ चाहिए -"]],[5113,["तो उन्होंने छाप-छूप दिया कि, \"एक भारतीय महिला","आई, ये वो हुआ।\" उसके बाद, तीसरे दिन उन्होंने","हमारा फोटोग्राफ देखा, अखबार में।"]],[5124,["तो वो दौड़े-दौड़े गए बताने के लिए कि,","\"यही वो लेडी है जिसने ठीक कर दिया।\""]],[5128,["तो उन्होंने फिर चिट्ठी लिखी व्यवस्थापकों को।","तो हमारे गाविन ब्राउन कर के साहब हैं,","उनके पास चिट्ठी आई।"]],[5135,["तो उन्होंने फिर एक चिट्ठी लिख के भेजी कि, \"माताजी","के लिए ये कोई आश्चर्य की बात नहीं है। ऐसा","पहले बहुत बार इंडिया में हो चुका है।\""]],[5142,["एक बार एक साहब हमारे साथ हमारे ट्रस्टी हैं, वो","हमारे साथ बैठे हुए कुछ बातचीत कर रहे थे।"]],[5150,["भूल गए कि उनको हाई कोर्ट जाना है और","एक केस है और उसको लड़ना है।"]],[5156,["जब घर गए, तो उनको फिर उसने फ़ोन किया","आशील ने कि, \"भई, क्या हुआ केस का?\""]],[5160,["तो कहा कि, \"अच्छा भई, मैं कल जा के देखता हूँ।\"","दूसरे दिन वो गए तो उन्होंने पूछा कि, \"भई, उस","केस का क्या हुआ?\""]],[5165,["कहने लगे, \"क्या मतलब, आप तो कल आए थे,","और केस जिरह हुई, और आपकी तरफ से","जजमेन्ट (फैसला) भी हो गया।\""]],[5173,["उनने जाके जजमेंट पढ़ा, उसमें तीन बार उनका नाम","लिखा था कि, \"इस टाइम प्रधान साहब ने बड़ी","ब्रिलिएंटली बात करी"]],[5180,["और बड़े इंटेलीजेंट पॉइंट्स निकाले, और कुछ","आउट ऑफ़ द वे चीज़ कह डाली,"]],[5184,["और इसमें तो कोई ये ही नहीं दिखता है,","और इनके ही फेवर में केस जाएगा।\""]],[5188,["तो वो तो मेरे ही साथ बैठे थे और आठ दस और","आदमी वहाँ बैठे थे। इस प्रकार अनेक बार हुआ।"]],[5195,["लेकिन इसमें कोई आश्चर्य की बात नहीं है, क्योंकि","अगर मैंने कहा परमात्मा ही आश्चर्यजनक है,","तो फिर इसमें आपको आश्चर्य क्यों है।"]],[5202,["अगर परमात्मा आपको सँभालने वाले बैठे हुए हैं,","तो उसका थोड़ा सा, आपको इसकी जानकारी","किसी प्रचीति से तो होगी न।"]],[5214,["तो प्रचीति मिलती रहती है जिससे आपका","विश्वास बढ़ते जाता है परमात्मा पे।"]],[5219,["लेकिन पार होने से पहले नहीं मिलेगी।","अब ये लड़का जो था ये पैदा पार था।"]],[5225,["बहुत से लोग मुझे मिलते हैं कहते हैं, \"माँ,","हमने आपको स्वप्न में देखा, हमने तो","पहले आपको देखा नहीं था।\""]],[5231,["बहुत से लोग - अब ये कैसे हो गया। अब इसकी","लम्बी चौड़ी बात है - ये तो दूसरी मशीन है।"]],[5242,["तुम्हें क्यों हँसी आ रही? सहज योगी ये बात बहुत","बार देख चुके - यहाँ हज़ारों ऐसे किस्से हो गए।"]],[5252,["एक्सीडेंट होगा नहीं। अगर वहाँ सहज योगी होगा,","तो एक्सीडेंट टल जाएगा, और हुआ भी, तो किसी","को चोट नहीं आएगी।"]],[5260,["हमारे एक सहज योगी - पहले हम किसी से कहते","नहीं थे कि सिगरेट मत पियो या कुछ करो।"]],[5266,["तो सिगरेट की उनको थोड़ी आदत थी,","ज़्यादा नहीं, सब छूट गया था।"]],[5269,["लेकिन एक दिन मोटर चलाते वक़्त हाथ में उनके","सिगरेट थी और उनके 5 - 6 दोस्त भी साथ में","सिगरेट पी रहे थे।"]],[5273,["सबने फाॅर्स किया कि सिगरेट रखो हाथ में।","कहने लगे, \"मैंने उसको पिया भी नहीं हाथ","में ही थी सिगरेट।"]],[5279,["इतने में हमारी मोटर जाकर के खड्डे में गिरी","और एकदम हम लोग उसके अंदर घुस गए,"]],[5284,["पता नहीं कैसे और जब बाहर आए, तो बिल्कुल हमें","कुछ नहीं हुआ था। सिर्फ मेरी ये उँगली, जिसमें","विशुद्धि चक्र होता है, वो ज़रा सी चोट खा गई।"]],[5294,["तब मैंने कान पकड़े कि अब मैं सिगरेट नहीं पिऊँगा।","और इतनी सी चोट खा गई।\" बता रहे थे वो कि,","\"इतनी सी मेरी उँगली चोट खा गई।\""]],[5305,["फिर परमात्मा का खेल आप देखिए, बड़ा मज़ा","आएगा। अभी तो जाना ही नहीं। जब जानिए, फिर","देखिए क्या खेल खेलते हैं।"]],[5314,["उसकी लीला अपरम्पार है बेटा। अब तुम्हारा विश्वास","बैठा न, इसलिए। ये विश्वास बैठाने के लिए ही","ये सब लीला करते हैं।"]],[5328,["यहाँ पर हर सहज योगी आपको अगर बताने लग जाए,","तो एक किताब लिख डाले। सब के एक-एक अनुभव हैं।"]],[5337,["हमारे वर्मा साहब हैं, वो खुदी इतनी ज़ोर से गिरे","थे। देखिए, उनको कोई विश्वास नहीं करेगा"]],[5342,["कि ये इतने ज़ोर से गिरे हुए और","बिलकुल मरते-मरते बचे हुए इंसान हैं।"]],[5346,["बहुत सारे लोग हैं इसकी कोई ऐसी बात नहीं,","लेकिन आप ने कह दिया आपकी मेहरबानी।"]],[5352,["सब लोगों को इससे विश्वास होता है। आपमें से","कोई ये बात उठ के कहे, बहुत बड़ी बात है।"]],[5361,["तो फिर ठीक है? अब इसका एक्सप्लनेशन क्या दें","- आपके साइंस में तो कुछ नहीं बैठने वाला।"]],[5366,["साइंस से परे, सेंसेस से परे। जो महाशय सेंसेस के बारे","में जानते हैं, वो क्या एक्सप्लनेशन इसका सुनेंगे।"]],[5374,["ये मशीन और है, मैंने आपसे कह दिया।","भगवान की मशीन और है।"]],[5381,["अच्छा पार हो लें, चलिए कोशिश करें, पर ये है कि,","जैसे आज सोमवार को आप आए हैं, अगले भी","सोमवार को आप आइए।"]],[5388,["ध्यान-धारणा करें। यहाँ पर हमारे और भी","लेक्चर होते हैं - इसमें उतरना पड़ता है।"]],[5393,["पहली चीज़ है योग को प्राप्त करें और दूसरी चीज़ है,","इसमें कुशलता आप प्रवीणता करें और परमात्मा के","आशीर्वाद से पूरी तरह से आप सिंचित रहें।"]],[5402,["साधक: कर्म बलवान है कि योग?","श्री माताजी: हाँ, बेटा?","साधक: कर्म बलवान है कि योग?"]],[5407,["सहज योगी: कर्म बलवान है माँ, या योग?","श्री माताजी: कर्म, कर्म बलवान है?","सहज योगी: या योग?"]],[5413,["श्री माताजी: योग सबसे बलवान है बेटा। कर्म का","तो कोई मतलब - कर्म तो सिर्फ एक भ्रम है।"]],[5418,["आप करते ही क्या हैं - ये भी भ्रम है। आप करते क्या","हैं? कोई मरी हुई चीज़ से मरी हुई चीज़ बना दें।"]],[5426,["आप ज़िंदा काम तो एक भी नहीं कर सकते ।","एक फूल से आप फल नहीं निकाल सकते।"]],[5432,["तो कर्म करते ही क्या हैं? आप लोग दिमागी","जमा खर्च कि, \"मैंने ये बुरा किया, मैंने अच्छा","किया,\" इसी में अपने को परेशान किए हुए हैं।"]],[5438,["साधक: जितने संस्कार करम हैं ना।","श्री माताजी: ऐं?","साधक: जितने संस्कार जो हैं वो करम हैं।"]],[5442,["श्री माताजी : तो वो भी इसमें अगर कोई आपके करम","खाने को बैठा है, तो आप क्यों परेशान हैं?"]],[5447,["कोई होता ही ऐसा है जो आपके करम सब खा जाए,","हो सकता है, हो तो सकता है कि नहीं?"]],[5454,["ठीक है, आप हम पे छोड़िए, आपके करम","ज़रा देखें तो क्या हैं।"]],[5460,["जब परमात्मा को आप जानते हैं, लेकिन समझते","नहीं हैं। परमात्मा जो है वो प्रेम का सागर है,"]],[5470,["दया का सागर है, क्षमा का सागर है - सब चीज़","आपकी एक क्षण में ख़तम कर सकता है।"]],[5476,["आप बिलकुल ये ना सोचिए, ये सोचना भी नुकसानदेह","है। अगर आप सोच रहे, \"मेरे पूर्व करम ख़राब थे, ये","था,\" सो तो कुछ बात बनने नहीं वाली।"]],[5486,["आप ये सोचिए कि, \"मैं आत्मा हूँ, और आत्मा","निर्दोष है, और मैं आत्मा ही बनना चाहता हूँ।\""]],[5493,["इसी विचार से जो आदमी आएंगे, वही पार","होएंगे, और जो इस तरह से सोचेंगे,"]],[5497,["\"मैं किसी काम का नहीं, और मैं बेकार हूँ, और मेरे","पूर्वजन्म ख़राब हैं,\" उनका कुछ नहीं बनने वाला।"]],[5503,["आपको तो मैं मंदिर बना रहीं हूँ, जो","परमात्मा का साम्राज्य है। ठीक है?"]],[5509,["मैं तो आपको नहीं मानतीं, आप कोई दोषी हैं -","मैं तो ये मानतीं हूँ, आप मंदिर हैं।"]],[5513,["हाँ बेटे, अब बहुत हो गया। जितने लेक्चर से ज़्यादा","अगर मैं सिर्फ आंसर (उत्तर) ही देतीं रहूँ - अच्छा एक","अब आखिरी सवाल।"]],[5519,["साधक: आत्मा और सूक्ष्म शरीर में क्या","रिलेशन (सम्बन्ध) है?"]],[5523,["श्री माताजी: आत्मा और सूक्ष्म शरीर - सूक्ष्म","शरीर जो होता है, वही जीवात्मा का जो जीव है,","उसे सक्ष्म शरीर कहते हैं।"]],[5530,["और आत्मा बिलकुल अछूती चीज़ है - समझे न?","अभी मैंने उसकी व्याख्या की है, फिर किसी दिन तुम","हमारे भाषण में सुन लेना, तो समझ लेना।"]],[5539,["अभी उसकी व्याख्या मैंने बता दी।","साधक : ये कहा जाता है माँ जी"]],[5547,["श्री माताजी : हूँ। अब फिर से बेटे - तुम ने","चार सवाल पूछ लिए।"]],[5549,["साधक : अगर परमिशन हो तो।","श्री माताजी : क्या कहा - कहा जाता है, छोड़","दो - अभी जो होता है, वो दिखा देते हैं न।"]],[5557,["साधक: एक बड़ा मामूली सा है सवाल।","श्री माताजी: हम्म"]],[5560,["साधक: ये अक्सर कहा जाता है कि, जो कुछ भी","होता है, उस विधाता की इच्छा से होता है।","श्री माताजी: ठीक है।"]],[5564,["साधक: मनुष्य जो भी करता है, चाहे वो नेक काम","करता है, या वो बुरे काम करता है"]],[5567,["श्री माताजी: नहीं ये नहीं कहा गया। ये बात","गलत है। नहीं, नहीं ये बात गलत है। ये आप","अपने मन से कह रहे है।"]],[5573,["साधक : मेरी विनती आपसे यही है, कि इसके ऊपर","थोड़ी सी लाइट थ्रो कीजिए, कि कहाँ तक ये","सही बात है।"]],[5577,["श्री माताजी : अच्छा, आप बैठिए, आप बैठिए,","आप बैठिए।"]],[5579,["परमात्मा जो करता है, वो उसकी इच्छा से होता है,","पर मनुष्य के लिए उसने स्वतंत्रता दे दी है।"]],[5585,["मनुष्य को उसने स्वतंत्रता दे दी और स्वतंत्रता","में उसने कहा, कि तुम आराम से रहो।"]],[5592,["पहले यही कहा - पहले मनुष्य को उसने ये","नहीं कहा कि तुम खोजो।"]],[5596,["नहीं कुछ नहीं कहा। उसने कहा कि, 'तुम अब","आराम से रहो।' बाइबिल में इसका उल्लेख","आपने सुना होगा"]],[5602,["कि उनको एक गार्डन दे दिया, उनसे कहा शान्ति से","बैठे रहो, ऐसे ही रहो। लेकिन इंसान को चैन कहाँ?"]],[5608,["उसने (सोचा) ऐसा क्यों कहा? जब ये गलत","रस्ते पे चल पड़ा, तो अब वो इतनी लम्बी-चौड़ी","चीज़ चल गया है -"]],[5618,["फिर उसके लिए अवतरण हुए, ये हुआ, सब परेशानी","हुई - नहीं तो कब के कब हो जाता ये काम।"]],[5623,["तो आपको स्वतंत्रता परमात्मा ने ज़रूर दी क्योंकि","स्वतंत्रता, इसको पाए बगैर, आप स्व के तंत्र","को नहीं जान पाएंगे।"]],[5630,["इसलिए स्वतंत्रता दी हुई है। आप भला करिए, बुरा","करिए, ये आपका है। बाकी परमात्मा जो है, वो सारा","कार्य करता है - इसमें कोई बात नहीं।"]],[5642,["आप अपना बिगाड़ना चाहें, तो बिगाड़ सकते हैं, अच्छा","करना चाहें, तो कर सकते हैं - उसको परमात्मा क्या","करे, क्योंकि आपको स्वतंत्रता दे दी।"]],[5649,["और जो दी हुई चीज़ वापस लेने के लिए वो","इंसान थोड़ी न है, वो तो भगवान हैं।"]],[5654,["अब जाइये, अब आपको अगर जाना है नर्क में, तो","जाइये - क्या करें? और अगर स्वर्ग में आना हैं,","तो भी आ सकते हैं।"]],[5665,["तो इतना लम्बा घुमाव करना पड़ गया। उस वक़्त","जल्दी से जो काम हो सकता था, उसके लिए","इंसान को इतना लम्बा घूमना पड़ा।"]],[5671,["अब तो रस्ते पे आ जाइए - ठीक है? स्वतंत्रता तो","आपकी है ही, इसीलिए तो हम बैठे लेक्चर दे रहे हैं।"]],[5679,["और अगर आपकी स्वतंत्रता नहीं होती, तो लेक्चर","देने की क्या ज़रुरत है ऐसे ही पार करा देते हैं।"]],[5685,["अगर आप स्वतंत्र नहीं होंगे, तो इस सम्पूर्ण","स्वतंत्रता तो आप समझ नहीं पाएंगे।"]],[5692,["पहले स्वतंत्र होना पड़ेगा। इसलिए आप स्वतंत्र हैं,","और आपकी स्वतंत्रता में ही हमारी विनती है,"]],[5700,["कि आप अपने आत्मसाक्षात्कार को पाएँ और","अपनी स्वतंत्रता से इसे स्वीकार्य करें।"]],[5708,["अब ठीक है? अब आँख बंद करिए। ऐसे हाथ रखें।"]],[5719,["आँख बंद कर लें। चश्मे वगैरह उतार लें तो अच्छा","रहेगा - आँख पे भी अच्छा असर आता है।","बस ऐसे हाथ रख लें।"]],[5739,["अब अपने मन से पूछिए कि, \"तू क्या विचार","कर रहा है?\" देखिये क्या विचार कर रहा है।"]],[5745,["अधिकतर लोग निर्विचार हैं इस वक़्त। आप","विचार करना चाहें तो कर सकते हैं,"]],[5757,["लेकिन आप आँख बंद करके अपने मन से","पूछें, \"तू क्या विचार कर रहा है?\""]],[5763,["चश्मा उतार लीजिए अच्छा रहेगा - आँख के","लिए फायदा करती है। उतार लीजिए।"]],[5775,["आँख को खोलिएगा नहीं, कृपया।"]],[5788,["अब फिर वही बात आ गई - आँख बंद रखिए","आपकी स्वतंत्रता। मैं आपकी स्वतंत्रता को नहीं","उल्लंघन कर सकती।"]],[5797,["उसको नहीं मैं पार कर सकती। आपकी स्वतंत्रता","में ही आपको कहना होगा कि, \"माँ मुझे","आत्मसाक्षात्कार चाहिए।\""]],[5806,["जब तक आप नहीं कहेंगे, मैं आपको ज़बरदस्ती","नहीं कर सकती हूँ, किसी भी प्रकार की।"]],[5820,["इसी जगह परमात्मा रुक जाता है कि","आपकी स्वतंत्रता आपकी अपनी है।"]],[5829,["आप चाहें तो अपने कर्म भोग लेकर रोते बैठे रहिए,","सर पीटते रहिए, और आप चाहें तो आत्मसाक्षात्कार","को पाएँ - ये सब आपके ऊपर है।"]],[5865,["कहना होगा कि, \"माँ मुझे आत्मसाक्षात्कार दीजिए।\""]],[6027,["आँख न खोलिए, लेकिन राइट हैंड हार्ट पे रखें -","राइट हैंड हार्ट पे। राइट हैंड, लेफ्ट में, हार्ट पर रखें।"]],[6039,["राइट हैंड को उठा के हार्ट पे रखें - ह्रदय पे","रखें, और एक बात कहें मन में, चाहे प्रश्न करें,","\"माँ क्या मैं आत्मा हूँ?\""]],[6069,["ह्रदय से पूछिए, \"क्या मैं आत्मा हूँ?","माँ क्या मैं आत्मा हूँ?\""]],[6092,["अब इसी हाथ को नीचे ले आयें - पेट पे रखें,","लेफ्ट साइड में। एक हाथ हमारी तरफ बना रहे।"]],[6103,["आँखें बंद करके पूछें, \"माँ, क्या मैं स्वयं का गुरु हूँ?\"","दस बार पूछिए। \"क्या मैं स्वयं का गुरु हूँ?\""]],[6112,["जब आप आत्मा हो गए, तो आत्मा आपका गुरु है,","इसलिए आपको पूछना चाहिए, \"क्या माँ मैं","स्वयं का गुरु हूँ?\""]],[6122,["नीचे रखें हाथ पेट पर। पेट पर लेफ्ट हैंड रखें जो ह्रदय","पे था, ह्रदय पे जो लेफ्ट हैंड है, ह्रदय पे जो राइट हैंड है,","उसे आप, राइट हैंड को आप पेट पर रखें।"]],[6135,["लेफ्ट हैंड मेरी ओर रखिए। जो राइट हैंड है, जो","ह्रदय पे था, उसे नीचे उतार के पेट पर रख के,","दस बार पूछिए,"]],[6147,["कि, \"माँ क्या मैं स्वयं का गुरु हूँ?\"","पूर्ण विश्वास के साथ पूछिए।"]],[6186,["अब इस हाथ को फिर से ह्रदय पे रख के बारह मर्तबा","कहें - ये सब चक्रों के, चक्रों की जितनी भी पंखुड़ियाँ हैं,"]],[6200,["उसके हिसाब से कह रहीं हूँ कि बारह मर्तबा आप","कहिए कि, \"मैं आत्मा हूँ और मैं निर्दोष हूँ।\""]],[6222,["\"मैं आत्मा हूँ और मैं निर्दोष हूँ,\"","बारह मर्तबा कहिए"]],[6267,["अब इस हाथ को अपने माथे पर आड़ा रखिए, माथे","पर। माथा पकड़ के जैसे बैठते हैं, माथे पर।"]],[6275,["माथा माने, जिसे कपाल कहते हैं - फॉरहेड।","फॉरहेड के ऊपर आड़ा रख के आप कहिए,"]],[6284,["कि \"माँ, मैंने सबको क्षमा कर दिया है,\" ह्रदय से","कहिए। सबको कर दीजिये, कोई बात कठिन नहीं,"]],[6289,["सिर्फ कहना मात्र है ह्रदय से, क्योंकि नहीं","क्षमा करने का मतलब ये है, कि आप खुदी","अपनी परेशानी बना रहे हैं।"]],[6297,["दूसरों को तो आप परेशान नहीं कर सकते,","अपने को परेशान किए हैं, इसलिए कह दीजिए,"]],[6301,["कि, \"माँ मैंने सबको क्षमा कर दिया है।\""]],[6333,["\"पूर्णतया मैंने क्षमा कर दिया है। मेरे मन में किसी के","लिए भी अब कोई दुःख नहीं है। मैंने सबको","क्षमा कर दिया है।\""]],[6358,["क्षमा कर दीजिए, सब को क्षमा कर दीजिए। आपका","सब बोझा उतर जायेगा। आप क्षमा कर दीजिए","पूरी तरह से।"]],[6372,["क्षमा करने से ही आप परमात्मा से ये भी कह","सकते हैं कि, \"मुझसे अगर कोई गलती हो,","तो उसे क्षमा करें।\""]],[6378,["पर उसमें अपने पे दोष न लें। अपने पर कोई","दोष न लें और कहें, परमात्मा से आप कहिए कि,"]],[6387,["\"मुझे आप क्षमा कर दीजिए।\" लेकिन आप","अपने पर कोई दोष मत लीजिए।"]],[6400,["अब इस हाथ को आप तालु स्थान पे रखिए। तालु","स्थान पर देखिए गर्मी आ रही है। अब तालु को","दबाइए उँगलियों से।"]],[6407,["देखिए तालु को गोल घुमाइए जैसे घडी के चक्र घूमते हैं","- आपको मैं स्वयं ही सिखा रहीं हूँ कि कुण्डलिनी","का जागरण कैसे करना है।"]],[6415,["और देखिए वहाँ गर्मी सी है। है? पहले","ज़रा गर्मी सी आ रही है।"]],[6436,["अब हाथ ऊपर उठा के देखें कि ठंडक आ रही क्या?","अब राइट हैंड मेरी ओर करिए, लेफ्ट हैंड से देखिए।"]],[6475,["कहिए कि, \"माँ, मुझे आत्मसाक्षात्कार दीजिए,\"","नम्रतापूर्वक, आप बहुत बड़ी चीज़ मांग रहे हैं।"]],[6507,["हाथ बदल-बदल के देखिए ठंडी हवा आ रही","या नहीं - सिर में पहले ठंडी हवा आएगी।"]],[6513,["यही कुण्डलिनी का जागरण है। एक हाथ हमारी","ओर रहने देना, दूसरा हाथ ऊपर। हाथ बदल-बदल","के देखिए।"]],[6524,["ऊपर उठा के हाथ को देखिए। बहुत ऊँचा नहीं,","सर्वसाधारण चार अंगुल ऊपर उठा के देखिए,","आ रही ठंडी?"]],[6541,["धीरे-धीरे बदलिए, जल्दी-जल्दी नहीं।"]],[6565,["अब दोनों हाथ ऐसे ऊपर कर लीजिए,","बिलकुल ऊपर, दोनों हाथ।"]],[6570,["और अब देखिए हाथ में ठंडक सी आ रही है क्या?","और पूछिए अंदर से सवाल कि, \"यही ब्रह्मशक्ति है,","ये सर्वव्यापी ब्रह्मशक्ति है?\""]],[6579,["ऊपर हाथ करके दोनों, आकाश की ओर। ऐसे लगा","जैसे कोई चीज़ अंदर चली जा रही है।"]],[6593,["अब नीचे हाथ करिए। दोनों हाथ ऐसे करके","देखिए हाथ में भी ठंडक आएगी - आ रही?"]],[6609,["जो लोग आज बिलकुल पहली मर्तबा आये हैं, शायद","उनको महसूस न हो क्योंकि बड़ी सूक्ष्म चीज़ है।"]],[6615,["लेकिन अधिकतर लोगों को हो गया है। बहुत","निर्विचारिता आ गई। देखिए मेरी ओर, आप आँख","खोल के देखिए, कि क्या विचार रुक गए हैं?"]],[6624,["मेरी ओर देखिए। रुक गए विचार? कोई विचार","आ रहे हैं? अब हाथ में ठंडक आ रही?","ज़रा फूँक, फूँक लें हाथ।"]],[6650,["अब हाथ की मेहनत लगेगी। अब फिर से हाथ रखिए।"]],[6713,["आ रही ठंडक अब? सूक्ष्म चीज़ है, ज़रा ख्याल","करिए। ध्यान। आँख बंद करें, आँख।"]],[6797,["शांति अंदर की, शांति प्रस्थापित हो गई। अब","हाथ में चैतन्य की लहरियाँ ठंडी-ठंडी हवा","की दृष्टि से आएंगीं।"]],[6807,["गरम आ रहीं हो, तो उनको ठंडा होना चाहिए। वो कैसे","करना है, क्या करना है, आप सेण्टर पर आइये।"]],[6815,["आने से, अभ्यास से, सब चीज़ व्यवस्थित हो जाएगी","और सहज योगी प्रतिष्ठित हो जाएंगे उसके बाद","स्वयं आप इसमें प्रवीण हो जाएंगे।"]],[6826,["इस सेण्टर में हमारे बहुत अच्छे कुछ सहज योगी हैं","और वो आपको बड़ा अच्छे से मार्गदर्शन करेंगे।"]],[6834,["लेकिन आप अपने प्रति आस्था रखें, अपना","विचार बनाइए, अपना ख्याल करें,"]],[6840,["और अपने जीवन का एक दिन, हफ्ते में सोमवार","का दिन, आप ज़रूर अपनी वृद्धि के लिए करें।"]],[6848,["इसी तरह से सारे संसार को बदलने के दिन","आ जाएंगे। आ जाओ।"]],[6862,["कोई भी, जिनके हाथ में अंदर ठंडक नहीं आई,","हाथ ऊपर करें - देखें कितने लोग हैं।"]],[6876,["बहुत कम लोग हैं, कोई हर्ज़ नहीं। आप लोग","अगर इधर तशरीफ़ ले आयें, तो ये लोग देख","लेंगे आप लोगों को, 3-4 जने जो हैं।"]],[6885,["इधर आ जाइए, आइए इधर, आ जाइए। नहीं, अब","आप बाद में करिए बात, पहले आ के पार हो जाओ।"]],[6892,["साधक: मेरे को आने की ज़रुरत नहीं मुझे आ रही है।","श्री माताजी: ऐं?"]],[6895,["साधक : मुझे वहाँ नहीं आना, मुझे आ रही है ठंडक।","श्री माताजी : फिर क्या है?"]],[6898,["साधक: ये कह रहे हैं, जितनी देर से मैं यहाँ","बैठा हूँ, तब से ही आ रही है।"]],[6902,["श्री माताजी: तुम्हें तो आ गई फिर क्या है","- अब तुम सीखो आगे कैसे करने का है।"]],[6906,["तो राजा बेटा हो तुम। क्या कह रहे?","सहज योगी: चाय"]],[6912,["श्री माताजी: चाय तो पी ली पूरा एक कप भर के।","बस चना ले आयें, बस और कुछ नहीं चाहिए। हाँ"]]]);
